package com.deathrecap;

import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

/**
 * Who attacked the player in a recap: an NPC or, in PvP, another player.
 */
@Data
@NoArgsConstructor
@AllArgsConstructor
public class Attacker
{
	private String name;
	/** Combat level, or 0 when unknown. */
	private int combatLevel;
	/** True for another player. */
	private boolean player;
}

package com.deathrecap;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.GridLayout;
import java.awt.Rectangle;
import java.awt.Window;
import java.util.ArrayList;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JComponent;
import javax.swing.JDialog;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;
import lombok.Value;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * Two recaps side by side, older on the left, with a list of what was different between them.
 */
final class CompareDialog extends JDialog
{
	private static final Color MUTED = ColorScheme.LIGHT_GRAY_COLOR.darker();

	/** The numbers compared for one recap. */
	@Value
	static class Facts
	{
		String killer;
		int damage;
		/** Food and potions used in the recap window. */
		int consumed;
		int lowestHp;
		/** Average HP percent when the killer hit; -1 when unknown. */
		int hpWhenHit;
		int fightTicks;
		/** Estimated gp lost; 0 for close calls and clips. */
		long lost;
		/** Food and potions still in the inventory; -1 when unknown. */
		int suppliesLeft;
	}

	CompareDialog(Window owner, DeathRecord first, DeathRecord second)
	{
		super(owner, "Compare recaps");
		DeathRecord a = first.getTimestamp() <= second.getTimestamp() ? first : second;
		DeathRecord b = a == first ? second : first;
		setDefaultCloseOperation(DISPOSE_ON_CLOSE);

		JPanel columns = new JPanel(new GridLayout(1, 2, 12, 0));
		columns.add(column(a, "Earlier"));
		columns.add(column(b, "Later"));

		JPanel diff = new JPanel();
		diff.setLayout(new BoxLayout(diff, BoxLayout.Y_AXIS));
		diff.setBorder(new EmptyBorder(10, 0, 0, 0));
		diff.add(label("What was different", Color.WHITE, true));
		List<String> lines = differences(facts(a), facts(b));
		if (lines.isEmpty())
		{
			lines = List.of("Nothing stands out: the two went much the same way.");
		}
		for (String line : lines)
		{
			diff.add(label("• " + line, Color.LIGHT_GRAY, false));
		}

		JPanel root = new JPanel(new BorderLayout());
		root.setBorder(new EmptyBorder(10, 10, 10, 10));
		root.add(columns, BorderLayout.CENTER);
		root.add(diff, BorderLayout.SOUTH);
		add(root);
		pack();
		setLocationRelativeTo(owner);
	}

	private static JPanel column(DeathRecord r, String title)
	{
		RecapAnalyzer.Summary summary = RecapAnalyzer.analyze(r);
		Facts f = facts(r, summary);
		JPanel col = new JPanel();
		col.setLayout(new BoxLayout(col, BoxLayout.Y_AXIS));
		col.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		col.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));
		col.add(label(title + ": " + RecapText.date(r.getTimestamp()), MUTED, false));
		col.add(label(RecapText.headline(r, summary), r.isCloseCall() ? HpGraph.FOOD : HpGraph.HIT, true));
		col.add(label(RecapText.place(r), MUTED, false));
		if (!r.getTicks().isEmpty())
		{
			col.add(new Graph(r));
		}
		List<String> lines = new ArrayList<>();
		lines.add("Damage taken: " + f.getDamage());
		lines.add("Lowest HP: " + f.getLowestHp());
		lines.add("Food and potions used: " + f.getConsumed());
		if (f.getHpWhenHit() >= 0)
		{
			lines.add("HP when " + f.getKiller() + " hit: " + f.getHpWhenHit() + "%");
		}
		if (f.getFightTicks() > 0)
		{
			lines.add(String.format("Fight length: %.1fs", f.getFightTicks() * RecapAnalyzer.TICK_SECONDS));
		}
		if (f.getSuppliesLeft() >= 0)
		{
			lines.add("Food and potions left: " + f.getSuppliesLeft());
		}
		if (f.getLost() > 0)
		{
			lines.add("Lost: about " + ItemsOnDeath.gp(f.getLost()) + " gp");
		}
		for (String line : lines)
		{
			col.add(label(line, Color.LIGHT_GRAY, false));
		}
		for (String finding : summary.getFindings())
		{
			col.add(label("• " + finding, MUTED, false));
		}
		return col;
	}

	static Facts facts(DeathRecord r)
	{
		return facts(r, RecapAnalyzer.analyze(r));
	}

	private static Facts facts(DeathRecord r, RecapAnalyzer.Summary summary)
	{
		StatEntry e = StatEntry.of(r, summary);
		int consumed = (int) r.getEvents().stream()
			.filter(ev -> ev.getType() == RecapEvent.Type.EAT || ev.getType() == RecapEvent.Type.DRINK).count();
		int lowest = r.getTicks().stream().mapToInt(TickSnapshot::getHp).min().orElse(0);
		DeathState s = r.getState();
		int left = s == null ? -1 : StatEntry.count(s.getFood()) + StatEntry.count(s.getPotions());
		return new Facts(RecapAnalyzer.label(r, summary.getKiller()), e.getDamage(), consumed, lowest, e.getHpWhenHit(),
			e.getFightTicks(), r.isDeath() ? e.getLost() : 0, left);
	}

	/** What changed from {@code a} (earlier) to {@code b} (later), plainly and without advice. */
	static List<String> differences(Facts a, Facts b)
	{
		List<String> out = new ArrayList<>();
		if (!a.getKiller().equals(b.getKiller()))
		{
			out.add("Different attacker: " + a.getKiller() + ", then " + b.getKiller());
		}
		int damage = b.getDamage() - a.getDamage();
		if (Math.abs(damage) >= Math.max(5, a.getDamage() / 5))
		{
			out.add(String.format("Took %d %s damage the second time (%d vs %d)", Math.abs(damage),
				damage > 0 ? "more" : "less", a.getDamage(), b.getDamage()));
		}
		if (a.getConsumed() != b.getConsumed())
		{
			out.add(String.format("Used %s food and potions (%d vs %d)", b.getConsumed() > a.getConsumed() ? "more" : "fewer",
				a.getConsumed(), b.getConsumed()));
		}
		if (a.getHpWhenHit() >= 0 && b.getHpWhenHit() >= 0 && Math.abs(a.getHpWhenHit() - b.getHpWhenHit()) >= 8)
		{
			out.add(String.format("HP was %s when hits landed (%d%% vs %d%%)",
				b.getHpWhenHit() > a.getHpWhenHit() ? "higher" : "lower", a.getHpWhenHit(), b.getHpWhenHit()));
		}
		if (a.getFightTicks() > 0 && b.getFightTicks() > 0
			&& Math.abs(a.getFightTicks() - b.getFightTicks()) >= Math.max(3, a.getFightTicks() * 3 / 10))
		{
			out.add(String.format("The fight was %s (%.1fs vs %.1fs)", b.getFightTicks() > a.getFightTicks() ? "longer" : "shorter",
				a.getFightTicks() * RecapAnalyzer.TICK_SECONDS, b.getFightTicks() * RecapAnalyzer.TICK_SECONDS));
		}
		if (a.getSuppliesLeft() >= 0 && b.getSuppliesLeft() >= 0 && (a.getSuppliesLeft() == 0) != (b.getSuppliesLeft() == 0))
		{
			out.add(b.getSuppliesLeft() == 0 ? "Ran out of food and potions the second time"
				: "Still had food or potions the second time (" + b.getSuppliesLeft() + ")");
		}
		if (a.getLost() != b.getLost() && (a.getLost() > 0 || b.getLost() > 0))
		{
			out.add("Lost about " + ItemsOnDeath.gp(a.getLost()) + " gp, then " + ItemsOnDeath.gp(b.getLost()) + " gp");
		}
		return out;
	}

	private static JLabel label(String text, Color colour, boolean bold)
	{
		JLabel l = new JLabel("<html><body style='width:280px'>" + text.replace("&", "&amp;").replace("<", "&lt;")
			+ "</body></html>");
		l.setForeground(colour);
		l.setFont(bold ? FontManager.getRunescapeBoldFont() : FontManager.getRunescapeSmallFont());
		l.setAlignmentX(LEFT_ALIGNMENT);
		l.setBorder(new EmptyBorder(1, 0, 1, 0));
		return l;
	}

	private static final class Graph extends JComponent
	{
		private final DeathRecord record;

		Graph(DeathRecord record)
		{
			this.record = record;
			Dimension size = new Dimension(300, 140);
			setPreferredSize(size);
			setMaximumSize(size);
			setFont(FontManager.getRunescapeSmallFont());
			setAlignmentX(LEFT_ALIGNMENT);
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			g.setFont(getFont());
			HpGraph.paint((Graphics2D) g, new Rectangle(0, 0, getWidth(), getHeight()), record);
		}
	}
}

package com.deathrecap;

import java.awt.Graphics2D;
import java.awt.Image;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;
import java.util.Queue;
import java.util.concurrent.ConcurrentLinkedQueue;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.RejectedExecutionException;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.ui.DrawManager;

/**
 * Captures the death screenshot and keeps a rolling buffer of frames for the replay GIF (at full size up to
 * {@link #MAX_FRAME_WIDTH} wide), so text in both is as readable as in the game. Frames are copied on the client thread into one of two
 * reusable buffers and compressed on a dedicated thread. Screenshots and GIFs are written on a second
 * thread, so a slow GIF (say, a close call's just before a death) never stops recording. If the frame
 * thread falls behind, frames are skipped.
 */
@Slf4j
class DeathCapture
{
	/** How long recording continues after the death, so the replay shows the death animation. */
	static final long AFTER_DEATH_MS = 2000;
	private static final int BUFFERS = 2;
	/** The last frame is held this long (hundredths of a second) before the GIF loops. */
	private static final int FINAL_FRAME_DELAY = 150;
	/** Replays whose full-quality frames are kept for sharper videos; older ones keep just the GIF. */
	static final int KEEP_FRAMES = 10;
	/** Replay frames wider than this (1440p, 4K) are scaled down; 1080p is kept at full size. */
	static final int MAX_FRAME_WIDTH = 1920;

	private static final class Frame
	{
		final long time;
		final byte[] jpeg;

		Frame(long time, byte[] jpeg)
		{
			this.time = time;
			this.jpeg = jpeg;
		}
	}

	private static final class Heard
	{
		final long time;
		final int id;
		final boolean area;

		Heard(long time, int id, boolean area)
		{
			this.time = time;
			this.id = id;
			this.area = area;
		}
	}

	/**
	 * Told the record, the saved file name and, for replays, when each frame was captured relative to the death in ms
	 * and the sounds heard meanwhile.
	 */
	interface Saved
	{
		void saved(DeathRecord record, String name, int[] times, List<ReplaySound> sounds);
	}

	/** Most sounds kept for one replay; a busy fight plays a few per tick. */
	static final int MAX_SOUNDS = 600;

	private final Client client;
	private final DrawManager drawManager;
	private final DeathRecapConfig config;
	private final DeathStore store;
	private final Runnable frameListener = this::onFrame;
	private final Deque<Frame> frames = new ArrayDeque<>();
	/** Sounds heard recently; guarded by itself. */
	private final Deque<Heard> sounds = new ArrayDeque<>();
	/** Copy buffers not currently being compressed; at most {@link #BUFFERS} exist. */
	private final Queue<BufferedImage> spare = new ConcurrentLinkedQueue<>();
	private final AtomicInteger buffers = new AtomicInteger();

	/** Compresses frames and takes each clip when it is due. */
	private ScheduledExecutorService worker;
	/** Writes screenshots and GIFs. */
	private ExecutorService writer;
	private long lastRequest;
	private boolean requestPending;
	/** The frame as it is compressed, reused for each frame. Frame thread only. */
	private BufferedImage prepared;

	DeathCapture(Client client, DrawManager drawManager, DeathRecapConfig config, DeathStore store)
	{
		this.client = client;
		this.drawManager = drawManager;
		this.config = config;
		this.store = store;
	}

	void start()
	{
		worker = Executors.newSingleThreadScheduledExecutor(r ->
		{
			Thread t = new Thread(r, "death-recap-frames");
			t.setDaemon(true);
			return t;
		});
		writer = Executors.newSingleThreadExecutor(r ->
		{
			Thread t = new Thread(r, "death-recap-media");
			t.setDaemon(true);
			return t;
		});
		drawManager.registerEveryFrameListener(frameListener);
	}

	void stop()
	{
		drawManager.unregisterEveryFrameListener(frameListener);
		if (worker != null)
		{
			worker.shutdownNow();
			worker = null;
		}
		if (writer != null)
		{
			writer.shutdownNow();
			writer = null;
		}
		clear();
	}

	void clear()
	{
		synchronized (frames)
		{
			frames.clear();
		}
		synchronized (sounds)
		{
			sounds.clear();
		}
		// Buffers still being compressed come back to spare afterwards and are counted until dropped here.
		while (spare.poll() != null)
		{
			buffers.decrementAndGet();
		}
	}

	/**
	 * Called on the client thread when the local player dies or has a close call. Each callback runs on
	 * the media thread once its file has been written.
	 */
	void captureDeath(long accountHash, DeathRecord record, Saved onScreenshot, Saved onReplay)
	{
		captureDeath(accountHash, record, AFTER_DEATH_MS, onScreenshot, onReplay);
	}

	/** As above, with the replay running {@code afterMs} past the record's timestamp. */
	void captureDeath(long accountHash, DeathRecord record, long afterMs, Saved onScreenshot, Saved onReplay)
	{
		ScheduledExecutorService w = worker;
		ExecutorService out = writer;
		if (w == null || out == null || !config.saveToDisk())
		{
			return;
		}
		long deathTime = record.getTimestamp();

		if (config.saveScreenshot())
		{
			drawManager.requestNextFrameListener(image ->
			{
				BufferedImage copy = copy(image);
				String name = deathTime + ".png";
				execute(out, () ->
				{
					try
					{
						store.writePng(accountHash, name, copy);
						onScreenshot.saved(record, name, null, null);
					}
					catch (Exception e)
					{
						log.warn("Unable to save death screenshot", e);
					}
				});
			});
		}

		if (config.recordReplay())
		{
			long from = deathTime - config.replaySeconds() * 1000L;
			long to = deathTime + afterMs;
			// The clip is taken on the frame thread when it's due, before older frames are dropped, and
			// written on the media thread, which may still be busy with an earlier GIF.
			w.schedule(() ->
			{
				List<Frame> clip = new ArrayList<>();
				synchronized (frames)
				{
					for (Frame f : frames)
					{
						if (f.time >= from && f.time <= to)
						{
							clip.add(f);
						}
					}
				}
				List<ReplaySound> heard = soundsBetween(from, to, deathTime);
				log.debug("Replay clip: {} frames, {} to {} ms from the death", clip.size(),
					clip.isEmpty() ? 0 : clip.get(0).time - deathTime, clip.isEmpty() ? 0 : clip.get(clip.size() - 1).time - deathTime);
				if (clip.size() >= 2)
				{
					execute(out, () -> writeReplay(accountHash, record, deathTime, clip, heard, onReplay));
				}
			}, afterMs + 100, TimeUnit.MILLISECONDS);
		}
	}

	private void writeReplay(long accountHash, DeathRecord record, long deathTime, List<Frame> clip, List<ReplaySound> heard,
		Saved onReplay)
	{
		String name = deathTime + ".gif";
		try
		{
			store.writeGif(accountHash, name, i -> FrameCodec.decode(clip.get(i).jpeg), delays(clip));
			int[] times = new int[clip.size()];
			for (int i = 0; i < times.length; i++)
			{
				times[i] = (int) (clip.get(i).time - deathTime);
			}
			try
			{
				List<byte[]> jpegs = new ArrayList<>(clip.size());
				for (Frame f : clip)
				{
					jpegs.add(f.jpeg);
				}
				store.writeFrames(accountHash, DeathStore.framesName(name), jpegs, times);
				store.pruneFrames(accountHash, KEEP_FRAMES);
			}
			catch (Exception e)
			{
				log.warn("Unable to save replay frames", e);
			}
			onReplay.saved(record, name, times, heard);
		}
		catch (Exception e)
		{
			log.warn("Unable to save death replay", e);
		}
	}

	/**
	 * Called on the client thread for each sound effect the game plays while recording. Times are taken now, so a
	 * sound lines up with the frame drawn when it started.
	 */
	void sound(int id, boolean area)
	{
		if (!config.recordReplay() || !config.saveToDisk() || !config.replaySounds())
		{
			return;
		}
		long now = System.currentTimeMillis();
		// Clips run longer after the key press than replays after a death, so keep enough for either.
		long keep = config.replaySeconds() * 1000L + 10_000;
		synchronized (sounds)
		{
			sounds.addLast(new Heard(now, id, area));
			while (!sounds.isEmpty() && (sounds.peekFirst().time < now - keep || sounds.size() > MAX_SOUNDS * 2))
			{
				sounds.pollFirst();
			}
		}
	}

	/** The sounds heard between two absolute times, with times relative to the death. */
	List<ReplaySound> soundsBetween(long from, long to, long deathTime)
	{
		List<ReplaySound> out = new ArrayList<>();
		synchronized (sounds)
		{
			for (Heard h : sounds)
			{
				if (h.time >= from && h.time <= to && out.size() < MAX_SOUNDS)
				{
					out.add(new ReplaySound((int) (h.time - deathTime), h.id, h.area));
				}
			}
		}
		return out;
	}

	private static void execute(ExecutorService executor, Runnable task)
	{
		try
		{
			executor.execute(task);
		}
		catch (RejectedExecutionException e)
		{
			// Shutting down.
		}
	}

	private void onFrame()
	{
		if (!config.recordReplay() || !config.saveToDisk() || client.getGameState() != GameState.LOGGED_IN)
		{
			if (!frames.isEmpty())
			{
				clear();
			}
			return;
		}
		long now = System.currentTimeMillis();
		long interval = 1000L / config.replayFps();
		// If a requested frame never arrived (e.g. the window was minimised), ask again.
		if (now - lastRequest < interval || (requestPending && now - lastRequest < 1000))
		{
			return;
		}
		lastRequest = now;
		requestPending = true;
		drawManager.requestNextFrameListener(image ->
		{
			requestPending = false;
			ScheduledExecutorService w = worker;
			BufferedImage copy = w == null ? null : buffer(image.getWidth(null), image.getHeight(null));
			if (copy == null)
			{
				return;
			}
			Graphics2D g = copy.createGraphics();
			g.drawImage(image, 0, 0, null);
			g.dispose();
			long time = System.currentTimeMillis();
			long keep = config.replaySeconds() * 1000L + AFTER_DEATH_MS + 500;
			try
			{
				w.execute(() ->
				{
					try
					{
						Frame frame = new Frame(time, FrameCodec.encode(prepare(copy)));
						synchronized (frames)
						{
							frames.addLast(frame);
							while (!frames.isEmpty() && frames.peekFirst().time < time - keep)
							{
								frames.pollFirst();
							}
						}
					}
					catch (Exception e)
					{
						log.debug("Unable to compress replay frame", e);
					}
					finally
					{
						spare.offer(copy);
					}
				});
			}
			catch (RejectedExecutionException e)
			{
				// Shutting down.
				spare.offer(copy);
			}
		});
	}

	/**
	 * Scales the frame down to {@link #MAX_FRAME_WIDTH} if wider, into a byte BGR image, which the JPEG encoder
	 * takes about a third faster than int RGB. Frame thread; the result is only good until the next call.
	 */
	private BufferedImage prepare(BufferedImage full)
	{
		int width = Math.min(full.getWidth(), MAX_FRAME_WIDTH);
		int height = width == full.getWidth() ? full.getHeight() : Math.max(2, (int) Math.round(full.getHeight() * (width / (double) full.getWidth())));
		if (prepared == null || prepared.getWidth() != width || prepared.getHeight() != height)
		{
			prepared = new BufferedImage(width, height, BufferedImage.TYPE_3BYTE_BGR);
		}
		Graphics2D g = prepared.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
		g.drawImage(full, 0, 0, width, height, null);
		g.dispose();
		return prepared;
	}

	/** A free copy buffer of the given size, or null if both are busy. */
	private BufferedImage buffer(int width, int height)
	{
		BufferedImage b;
		while ((b = spare.poll()) != null)
		{
			if (b.getWidth() == width && b.getHeight() == height)
			{
				return b;
			}
			// The window was resized; replace this buffer.
			buffers.decrementAndGet();
		}
		if (buffers.incrementAndGet() > BUFFERS)
		{
			buffers.decrementAndGet();
			return null;
		}
		return new BufferedImage(width, height, BufferedImage.TYPE_INT_RGB);
	}

	private static BufferedImage copy(Image image)
	{
		BufferedImage out = new BufferedImage(image.getWidth(null), image.getHeight(null), BufferedImage.TYPE_INT_RGB);
		Graphics2D g = out.createGraphics();
		g.drawImage(image, 0, 0, null);
		g.dispose();
		return out;
	}

	/** Uses the real time between captured frames so the replay plays back at game speed. */
	static int[] delays(List<Frame> clip)
	{
		int[] delays = new int[clip.size()];
		for (int i = 0; i < clip.size() - 1; i++)
		{
			long ms = clip.get(i + 1).time - clip.get(i).time;
			delays[i] = (int) Math.max(2, Math.min(100, Math.round(ms / 10.0)));
		}
		delays[delays.length - 1] = FINAL_FRAME_DELAY;
		return delays;
	}
}

package com.deathrecap;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import lombok.Getter;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.worldmap.WorldMapOverlay;
import net.runelite.client.ui.overlay.worldmap.WorldMapPoint;
import net.runelite.client.ui.overlay.worldmap.WorldMapPointManager;

/**
 * A marker on the world map for every death (and, if wanted, close call) with a known location, coloured
 * by killer. Hovering shows who and when; right-clicking offers to open the recap.
 */
final class DeathMap
{
	private static final int SIZE = 11;
	/** The most "Open recap" entries added for a stack of markers. */
	static final int MAX_MENU = 5;

	static final class Marker extends WorldMapPoint
	{
		@Getter
		private final long timestamp;
		@Getter
		private final String killer;

		Marker(WorldPoint point, BufferedImage image, long timestamp, String killer)
		{
			super(point, image);
			this.timestamp = timestamp;
			this.killer = killer;
		}

		@Override
		public boolean equals(Object o)
		{
			return o == this;
		}

		@Override
		public int hashCode()
		{
			return System.identityHashCode(this);
		}
	}

	private final Client client;
	private final WorldMapPointManager points;
	private final WorldMapOverlay overlay;
	private final Map<String, BufferedImage> images = new HashMap<>();
	private volatile List<Marker> markers = List.of();
	/** Set when the plugin stops, so a late refresh can't put markers back. */
	private boolean closed;

	DeathMap(Client client, WorldMapPointManager points, WorldMapOverlay overlay)
	{
		this.client = client;
		this.points = points;
		this.overlay = overlay;
	}

	/** Replaces the markers with one per located entry. Any thread. */
	synchronized void show(List<StatEntry> entries, boolean closeCalls)
	{
		if (closed)
		{
			return;
		}
		List<Marker> next = new ArrayList<>();
		for (StatEntry e : entries)
		{
			if (!e.hasLocation() || e.isCloseCall() && !closeCalls)
			{
				continue;
			}
			String killer = DeathStats.name(e);
			Marker m = new Marker(new WorldPoint(e.getX(), e.getY(), e.getPlane()), image(killer, e.isCloseCall()),
				e.getTimestamp(), killer);
			m.setName("Death Recap");
			m.setTooltip(tooltip(e, killer));
			m.setSnapToEdge(false);
			m.setJumpOnClick(false);
			next.add(m);
		}
		points.removeIf(p -> p instanceof Marker);
		next.forEach(points::add);
		markers = next;
	}

	synchronized void close()
	{
		closed = true;
		clear();
	}

	synchronized void clear()
	{
		points.removeIf(p -> p instanceof Marker);
		markers = List.of();
	}

	static String tooltip(StatEntry e, String killer)
	{
		String what = e.isCloseCall() ? "Close call: " : "Died to ";
		return what + killer + "<br>" + RecapText.date(e.getTimestamp())
			+ (e.getLost() > 0 && !e.isCloseCall() ? " · " + ItemsOnDeath.gp(e.getLost()) + " gp" : "");
	}

	/** The markers under the mouse while the world map is open, newest first. Client thread. */
	List<Marker> hovered()
	{
		List<Marker> current = markers;
		Widget map = client.getWidget(InterfaceID.Worldmap.MAP_CONTAINER);
		if (current.isEmpty() || map == null || map.isHidden())
		{
			return List.of();
		}
		Point mouse = client.getMouseCanvasPosition();
		List<Marker> hit = new ArrayList<>();
		for (Marker m : current)
		{
			Point p = overlay.mapWorldPointToGraphicsPoint(m.getWorldPoint());
			if (p != null && Math.abs(p.getX() - mouse.getX()) <= SIZE / 2 + 1 && Math.abs(p.getY() - mouse.getY()) <= SIZE / 2 + 1
				&& map.getBounds().contains(mouse.getX(), mouse.getY()))
			{
				hit.add(m);
			}
		}
		hit.sort((a, b) -> Long.compare(b.getTimestamp(), a.getTimestamp()));
		return hit;
	}

	private BufferedImage image(String killer, boolean hollow)
	{
		return images.computeIfAbsent(killer + (hollow ? "/ring" : ""), k -> draw(DeathStats.colour(killer), hollow));
	}

	/** A dot in the killer's colour with a dark rim; close calls are a ring. */
	static BufferedImage draw(Color colour, boolean hollow)
	{
		BufferedImage img = new BufferedImage(SIZE, SIZE, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(Color.BLACK);
		g.fillOval(0, 0, SIZE - 1, SIZE - 1);
		g.setColor(colour);
		if (hollow)
		{
			g.setStroke(new BasicStroke(2.5f));
			g.drawOval(2, 2, SIZE - 5, SIZE - 5);
		}
		else
		{
			g.fillOval(1, 1, SIZE - 3, SIZE - 3);
		}
		g.dispose();
		return img;
	}
}

