package com.deathrecap;

import java.awt.Color;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Predicate;
import java.util.function.ToDoubleFunction;
import lombok.Value;

/**
 * Lifetime totals over every recorded death and close call, overall and per killer.
 */
final class DeathStats
{
	/** Entries needed before a killer's trend is worked out. */
	static final int TREND_MIN = 4;

	@Value
	static class Killer
	{
		String name;
		int deaths;
		int closeCalls;
		int averageDamage;
		int withoutEating;
		/** Estimated gp lost to this killer. */
		long lost;
		/** Average HP percent when its hits landed; -1 when unknown. */
		int hpWhenHit;
		/** Average ticks from the first damage to the death or close call; 0 when unknown. */
		int fightTicks;
		/** Its deaths and close calls, oldest first. */
		List<StatEntry> entries;
		/** Null with fewer than {@link #TREND_MIN} entries. */
		Trend trend;
	}

	@Value
	static class Trend
	{
		/** Positive when the recent half went better than the earlier half, negative when worse. */
		int score;
		/** One line per thing that changed, e.g. "You eat before dying more often". */
		List<String> reasons;

		String verdict()
		{
			return score > 0 ? "Improving" : score < 0 ? "Getting worse" : "About the same";
		}
	}

	@Value
	static class Report
	{
		int deaths;
		int closeCalls;
		/** Average damage taken in the recap window before a death. */
		int averageDamage;
		/** Deaths with no food or potion in the recap window. */
		int withoutEating;
		/** Sorted by deaths, then close calls. */
		List<Killer> killers;
		/** Estimated gp lost over every death. */
		long lost;
		/** Deaths and gp lost since the session started. */
		int sessionDeaths;
		long sessionLost;
		/** The death that cost the most gp; null when no death lost anything. */
		StatEntry mostExpensive;
		/** Deaths with food or potions still in the inventory. */
		int withSupplies;

		Killer killer(String name)
		{
			for (Killer k : killers)
			{
				if (k.getName().equals(name))
				{
					return k;
				}
			}
			return null;
		}
	}

	private DeathStats()
	{
	}

	/** A steady colour for a killer, the same on the world map and in the panel. */
	static Color colour(String killer)
	{
		int h = (killer == null ? "Unknown" : killer).hashCode() * 0x9E3779B1;
		return Color.getHSBColor((h >>> 16) / 65536f, 0.7f, 0.95f);
	}

	static String name(StatEntry e)
	{
		return e.getKiller() == null ? "Unknown" : e.getKiller();
	}

	/** @param sessionStart epoch millis; deaths from then on count toward the session totals */
	static Report compute(List<StatEntry> entries, long sessionStart)
	{
		long lost = 0;
		int sessionDeaths = 0;
		long sessionLost = 0;
		StatEntry mostExpensive = null;
		int withSupplies = 0;
		Map<String, List<StatEntry>> byKiller = new LinkedHashMap<>();
		int deaths = 0;
		int closeCalls = 0;
		long damage = 0;
		int hungry = 0;
		List<StatEntry> sorted = new ArrayList<>(entries);
		sorted.sort(Comparator.comparingLong(StatEntry::getTimestamp));
		for (StatEntry e : sorted)
		{
			byKiller.computeIfAbsent(name(e), n -> new ArrayList<>()).add(e);
			if (e.isCloseCall())
			{
				closeCalls++;
				continue;
			}
			deaths++;
			damage += e.getDamage();
			lost += e.getLost();
			if (e.isSuppliesLeft())
			{
				withSupplies++;
			}
			if (e.getTimestamp() >= sessionStart)
			{
				sessionDeaths++;
				sessionLost += e.getLost();
			}
			if (e.getLost() > 0 && (mostExpensive == null || e.getLost() > mostExpensive.getLost()))
			{
				mostExpensive = e;
			}
			if (!e.isAte())
			{
				hungry++;
			}
		}
		List<Killer> killers = new ArrayList<>();
		for (Map.Entry<String, List<StatEntry>> en : byKiller.entrySet())
		{
			killers.add(killer(en.getKey(), en.getValue()));
		}
		killers.sort(Comparator.comparingInt(Killer::getDeaths).thenComparingInt(Killer::getCloseCalls).reversed());
		return new Report(deaths, closeCalls, deaths == 0 ? 0 : (int) Math.round((double) damage / deaths), hungry, killers,
			lost, sessionDeaths, sessionLost, mostExpensive, withSupplies);
	}

	private static Killer killer(String name, List<StatEntry> list)
	{
		int deaths = 0;
		int damage = 0;
		int hungry = 0;
		long lost = 0;
		for (StatEntry e : list)
		{
			if (e.isCloseCall())
			{
				continue;
			}
			deaths++;
			damage += e.getDamage();
			lost += e.getLost();
			if (!e.isAte())
			{
				hungry++;
			}
		}
		double hp = average(list, e -> e.getHpWhenHit() >= 0, StatEntry::getHpWhenHit);
		double fight = average(list, e -> e.getFightTicks() > 0, StatEntry::getFightTicks);
		return new Killer(name, deaths, list.size() - deaths, deaths == 0 ? 0 : Math.round((float) damage / deaths),
			hungry, lost, Double.isNaN(hp) ? -1 : (int) Math.round(hp), Double.isNaN(fight) ? 0 : (int) Math.round(fight),
			List.copyOf(list), trend(list));
	}

	/** Compares the earlier and the recent half of a killer's entries (oldest first). */
	static Trend trend(List<StatEntry> list)
	{
		if (list.size() < TREND_MIN)
		{
			return null;
		}
		List<StatEntry> early = list.subList(0, list.size() / 2);
		List<StatEntry> recent = list.subList(list.size() / 2, list.size());
		int score = 0;
		List<String> reasons = new ArrayList<>();

		double survived = share(recent, StatEntry::isCloseCall) - share(early, StatEntry::isCloseCall);
		if (Math.abs(survived) >= 0.15)
		{
			score += survived > 0 ? 1 : -1;
			reasons.add(survived > 0 ? "You survive more of its close calls" : "More of its close calls end in death");
		}

		Predicate<StatEntry> death = e -> !e.isCloseCall();
		double ate = share(filter(recent, death), StatEntry::isAte) - share(filter(early, death), StatEntry::isAte);
		if (!Double.isNaN(ate) && Math.abs(ate) >= 0.25)
		{
			score += ate > 0 ? 1 : -1;
			reasons.add(ate > 0 ? "You eat before dying more often" : "You eat before dying less often");
		}

		double hp = average(recent, e -> e.getHpWhenHit() >= 0, StatEntry::getHpWhenHit)
			- average(early, e -> e.getHpWhenHit() >= 0, StatEntry::getHpWhenHit);
		if (!Double.isNaN(hp) && Math.abs(hp) >= 8)
		{
			score += hp > 0 ? 1 : -1;
			reasons.add(String.format("Your HP when it hits is %s (%+d%%)", hp > 0 ? "higher" : "lower", (int) Math.round(hp)));
		}

		double fight = average(recent, e -> e.getFightTicks() > 0, StatEntry::getFightTicks)
			- average(early, e -> e.getFightTicks() > 0, StatEntry::getFightTicks);
		double base = average(early, e -> e.getFightTicks() > 0, StatEntry::getFightTicks);
		if (!Double.isNaN(fight) && base > 0 && Math.abs(fight) / base >= 0.3)
		{
			reasons.add(fight > 0 ? "Fights last longer" : "Fights end sooner");
		}
		return new Trend(score, reasons);
	}

	private static List<StatEntry> filter(List<StatEntry> list, Predicate<StatEntry> keep)
	{
		List<StatEntry> out = new ArrayList<>();
		for (StatEntry e : list)
		{
			if (keep.test(e))
			{
				out.add(e);
			}
		}
		return out;
	}

	/** Fraction of {@code list} matching, NaN when empty. */
	private static double share(List<StatEntry> list, Predicate<StatEntry> match)
	{
		return list.isEmpty() ? Double.NaN : (double) filter(list, match).size() / list.size();
	}

	/** Average over the entries that have a value, NaN when none do. */
	private static double average(List<StatEntry> list, Predicate<StatEntry> has, ToDoubleFunction<StatEntry> value)
	{
		return filter(list, has).stream().mapToDouble(value).average().orElse(Double.NaN);
	}
}

package com.deathrecap;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.io.Reader;
import java.io.Writer;
import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;
import java.util.stream.Stream;
import javax.imageio.ImageIO;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Filepath;

/**
 * Reads and writes one JSON file of recaps per account, lifetime stats, and a media folder of screenshots, replays and share cards. Callers must run these off the client thread.
 */
@Slf4j
class DeathStore
{
	private static final Type LIST_TYPE = new TypeToken<List<DeathRecord>>()
	{
	}.getType();
	private static final Type STATS_TYPE = new TypeToken<List<StatEntry>>()
	{
	}.getType();

	private final Gson gson;
	/** Ending of a replay's full-quality frames file. */
	static final String FRAMES = ".frames";
	private final Filepath directory;

	DeathStore(Gson gson, Filepath directory)
	{
		this.gson = gson;
		this.directory = directory;
	}

	List<DeathRecord> load(long accountHash)
	{
		Filepath file = file(accountHash);
		if (!file.exists())
		{
			return new ArrayList<>();
		}
		try (Reader reader = file.openReader())
		{
			List<DeathRecord> records = gson.fromJson(reader, LIST_TYPE);
			return records != null ? records : new ArrayList<>();
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Unable to read death recaps", e);
			return new ArrayList<>();
		}
	}

	void save(long accountHash, List<DeathRecord> records)
	{
		Filepath file = file(accountHash);
		try (Writer writer = file.openWriter())
		{
			gson.toJson(records, LIST_TYPE, writer);
		}
		catch (IOException e)
		{
			log.warn("Unable to save death recaps", e);
		}
	}

	/** Lifetime stats, or null if this account has none saved yet. */
	List<StatEntry> loadStats(long accountHash)
	{
		Filepath file = statsFile(accountHash);
		if (!file.exists())
		{
			return null;
		}
		try (Reader reader = file.openReader())
		{
			List<StatEntry> stats = gson.fromJson(reader, STATS_TYPE);
			return stats != null ? stats : new ArrayList<>();
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Unable to read death stats", e);
			return new ArrayList<>();
		}
	}

	void saveStats(long accountHash, List<StatEntry> stats)
	{
		try (Writer writer = statsFile(accountHash).openWriter())
		{
			gson.toJson(stats, STATS_TYPE, writer);
		}
		catch (IOException e)
		{
			log.warn("Unable to save death stats", e);
		}
	}

	Filepath media(long accountHash, String name)
	{
		return mediaDir(accountHash).join(name);
	}

	Filepath mediaDir(long accountHash)
	{
		return directory.join("media", Long.toUnsignedString(accountHash));
	}

	void writePng(long accountHash, String name, BufferedImage image) throws IOException
	{
		mediaDir(accountHash).createDirectories();
		try (OutputStream out = media(accountHash, name).openOutputStream())
		{
			ImageIO.write(image, "png", out);
		}
	}

	void writeGif(long accountHash, String name, GifWriter.Frames frames, int[] delays) throws IOException
	{
		mediaDir(accountHash).createDirectories();
		try (OutputStream out = media(accountHash, name).openOutputStream())
		{
			GifWriter.write(frames, delays, out);
		}
	}

	/** Writes a replay's full-quality frames; see {@link ReplayFrames#writeFrames}. */
	void writeFrames(long accountHash, String name, List<byte[]> jpegs, int[] times) throws IOException
	{
		mediaDir(accountHash).createDirectories();
		try (OutputStream out = media(accountHash, name).openOutputStream())
		{
			ReplayFrames.writeFrames(out, jpegs, times);
		}
	}

	/** The name of the full-quality frames saved beside a replay GIF, or null. */
	static String framesName(String replay)
	{
		return replay == null || !replay.endsWith(".gif") ? null : replay.substring(0, replay.length() - 4) + FRAMES;
	}

	/** A replay's full-quality frames if they're still kept, otherwise its GIF. */
	byte[] readReplay(long accountHash, String replay) throws IOException
	{
		String frames = framesName(replay);
		if (frames != null && media(accountHash, frames).isFile())
		{
			try
			{
				return read(accountHash, frames);
			}
			catch (IOException e)
			{
				log.debug("Unable to read {}", frames, e);
			}
		}
		return read(accountHash, replay);
	}

	/**
	 * Keeps full-quality frames for only the newest {@code keep} replays, as each takes 10-30 MB. Older replays
	 * still have their GIFs.
	 */
	void pruneFrames(long accountHash, int keep)
	{
		Filepath dir = mediaDir(accountHash);
		if (!dir.isDirectory())
		{
			return;
		}
		try (Stream<Filepath> files = dir.walk(1))
		{
			List<Filepath> all = files.filter(f -> f.isFile() && f.getFileName().endsWith(FRAMES))
				.sorted(Comparator.comparingLong(DeathStore::timeOf).reversed())
				.collect(Collectors.toList());
			for (Filepath f : all.subList(Math.min(keep, all.size()), all.size()))
			{
				f.deleteIfExists();
			}
		}
		catch (IOException e)
		{
			log.warn("Unable to tidy replay frames", e);
		}
	}

	private static long timeOf(Filepath file)
	{
		String name = file.getFileName();
		try
		{
			return Long.parseLong(name.substring(0, name.length() - FRAMES.length()));
		}
		catch (NumberFormatException e)
		{
			return 0;
		}
	}

	byte[] read(long accountHash, String name) throws IOException
	{
		try (InputStream in = media(accountHash, name).openInputStream())
		{
			return in.readAllBytes();
		}
	}

	void deleteMedia(long accountHash, DeathRecord record)
	{
		for (String name : new String[]{record.getScreenshot(), record.getReplay(), framesName(record.getReplay()), record.getCard()})
		{
			if (name != null)
			{
				try
				{
					media(accountHash, name).deleteIfExists();
				}
				catch (IOException e)
				{
					log.warn("Unable to delete {}", name, e);
				}
			}
		}
	}

	/**
	 * Deletes media files that no saved recap refers to, such as ones left behind by a crash.
	 */
	void deleteOrphans(long accountHash, List<DeathRecord> records)
	{
		Filepath dir = mediaDir(accountHash);
		if (!dir.isDirectory())
		{
			return;
		}
		Set<String> keep = new HashSet<>();
		for (DeathRecord r : records)
		{
			keep.add(r.getScreenshot());
			keep.add(r.getReplay());
			keep.add(framesName(r.getReplay()));
			keep.add(r.getCard());
		}
		try (Stream<Filepath> files = dir.walk(1))
		{
			for (Filepath f : files.filter(Filepath::isFile).collect(Collectors.toList()))
			{
				if (!keep.contains(f.getFileName()))
				{
					f.deleteIfExists();
				}
			}
		}
		catch (IOException e)
		{
			log.warn("Unable to clean up death recap media", e);
		}
	}

	private Filepath statsFile(long accountHash)
	{
		return directory.join("stats-" + Long.toUnsignedString(accountHash) + ".json");
	}

	private Filepath file(long accountHash)
	{
		return directory.join("deaths-" + Long.toUnsignedString(accountHash) + ".json");
	}
}

package com.deathrecap;

import java.awt.image.BufferedImage;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import javax.imageio.IIOImage;
import javax.imageio.ImageIO;
import javax.imageio.ImageTypeSpecifier;
import javax.imageio.ImageWriteParam;
import javax.imageio.ImageWriter;
import javax.imageio.metadata.IIOMetadata;
import javax.imageio.metadata.IIOMetadataNode;
import javax.imageio.stream.ImageOutputStream;
import javax.imageio.stream.MemoryCacheImageOutputStream;
import org.w3c.dom.NodeList;

/**
 * Compresses replay frames while they wait in memory. A full-size frame is several megabytes raw but a
 * few hundred kilobytes as a high-quality JPEG. Chroma subsampling is turned off so coloured text such as
 * hitsplats and overhead messages stays sharp.
 */
final class FrameCodec
{
	private static final String FORMAT = "javax_imageio_jpeg_image_1.0";
	private static final float QUALITY = 0.92f;

	private FrameCodec()
	{
	}

	static byte[] encode(BufferedImage image) throws IOException
	{
		ImageWriter writer = ImageIO.getImageWritersByFormatName("jpeg").next();
		ByteArrayOutputStream bytes = new ByteArrayOutputStream(256 * 1024);
		// In memory: ImageIO would otherwise buffer every frame through a temporary file.
		try (ImageOutputStream out = new MemoryCacheImageOutputStream(bytes))
		{
			writer.setOutput(out);
			ImageWriteParam param = writer.getDefaultWriteParam();
			param.setCompressionMode(ImageWriteParam.MODE_EXPLICIT);
			param.setCompressionQuality(QUALITY);

			IIOMetadata meta = writer.getDefaultImageMetadata(new ImageTypeSpecifier(image), param);
			IIOMetadataNode root = (IIOMetadataNode) meta.getAsTree(FORMAT);
			NodeList components = root.getElementsByTagName("componentSpec");
			for (int i = 0; i < components.getLength(); i++)
			{
				IIOMetadataNode c = (IIOMetadataNode) components.item(i);
				c.setAttribute("HsamplingFactor", "1");
				c.setAttribute("VsamplingFactor", "1");
			}
			meta.setFromTree(FORMAT, root);
			writer.write(null, new IIOImage(image, null, meta), param);
		}
		finally
		{
			writer.dispose();
		}
		return bytes.toByteArray();
	}

	static BufferedImage decode(byte[] jpeg) throws IOException
	{
		BufferedImage image = ImageIO.read(new ByteArrayInputStream(jpeg));
		if (image == null)
		{
			throw new IOException("Unreadable replay frame");
		}
		return image;
	}
}

package com.deathrecap;

import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.io.OutputStream;
import javax.imageio.IIOImage;
import javax.imageio.ImageIO;
import javax.imageio.ImageTypeSpecifier;
import javax.imageio.ImageWriter;
import javax.imageio.metadata.IIOMetadata;
import javax.imageio.metadata.IIOMetadataNode;
import javax.imageio.stream.ImageOutputStream;

/**
 * Writes a looping animated GIF with the JDK's own encoder. Frames are read one at a time so only two
 * are ever in memory, and after the first frame only the area that changed is written, which keeps
 * full-size replays small when the camera is still.
 */
final class GifWriter
{
	private static final String FORMAT = "javax_imageio_gif_image_1.0";

	interface Frames
	{
		BufferedImage get(int index) throws IOException;
	}

	private GifWriter()
	{
	}

	/**
	 * @param delays per-frame display time in hundredths of a second; its length is the frame count
	 */
	static void write(Frames frames, int[] delays, OutputStream out) throws IOException
	{
		ImageWriter writer = ImageIO.getImageWritersByFormatName("gif").next();
		try (ImageOutputStream ios = ImageIO.createImageOutputStream(out))
		{
			writer.setOutput(ios);
			writer.prepareWriteSequence(null);
			int[] previous = null;
			int width = 0;
			int height = 0;
			for (int i = 0; i < delays.length; i++)
			{
				BufferedImage frame = frames.get(i);
				if (i == 0)
				{
					width = frame.getWidth();
					height = frame.getHeight();
				}
				int[] pixels = pixels(frame, width, height);
				Rectangle area = previous == null ? new Rectangle(0, 0, width, height) : changed(previous, pixels, width, height);
				previous = pixels;

				BufferedImage part = crop(pixels, width, area);
				IIOMetadata meta = writer.getDefaultImageMetadata(ImageTypeSpecifier.createFromRenderedImage(part), null);
				IIOMetadataNode root = (IIOMetadataNode) meta.getAsTree(FORMAT);

				IIOMetadataNode descriptor = child(root, "ImageDescriptor");
				descriptor.setAttribute("imageLeftPosition", Integer.toString(area.x));
				descriptor.setAttribute("imageTopPosition", Integer.toString(area.y));
				descriptor.setAttribute("imageWidth", Integer.toString(area.width));
				descriptor.setAttribute("imageHeight", Integer.toString(area.height));
				descriptor.setAttribute("interlaceFlag", "FALSE");

				IIOMetadataNode gce = child(root, "GraphicControlExtension");
				gce.setAttribute("disposalMethod", "doNotDispose");
				gce.setAttribute("userInputFlag", "FALSE");
				gce.setAttribute("transparentColorFlag", "FALSE");
				gce.setAttribute("transparentColorIndex", "0");
				gce.setAttribute("delayTime", Integer.toString(delays[i]));

				if (i == 0)
				{
					// NETSCAPE2.0 extension with a loop count of 0: loop forever.
					IIOMetadataNode app = new IIOMetadataNode("ApplicationExtension");
					app.setAttribute("applicationID", "NETSCAPE");
					app.setAttribute("authenticationCode", "2.0");
					app.setUserObject(new byte[]{1, 0, 0});
					child(root, "ApplicationExtensions").appendChild(app);
				}

				meta.setFromTree(FORMAT, root);
				writer.writeToSequence(new IIOImage(part, null, meta), null);
			}
			writer.endWriteSequence();
		}
		finally
		{
			writer.dispose();
		}
	}

	/** Pixels of the frame at the replay's size; a frame of another size (the window was resized) is scaled. */
	private static int[] pixels(BufferedImage frame, int width, int height)
	{
		if (frame.getWidth() != width || frame.getHeight() != height)
		{
			BufferedImage fitted = new BufferedImage(width, height, BufferedImage.TYPE_INT_RGB);
			Graphics2D g = fitted.createGraphics();
			g.drawImage(frame, 0, 0, width, height, null);
			g.dispose();
			frame = fitted;
		}
		return frame.getRGB(0, 0, width, height, null, 0, width);
	}

	/** The smallest rectangle holding every pixel that differs, or a single pixel if nothing changed. */
	static Rectangle changed(int[] a, int[] b, int width, int height)
	{
		int minX = width;
		int minY = height;
		int maxX = -1;
		int maxY = -1;
		for (int y = 0; y < height; y++)
		{
			int row = y * width;
			for (int x = 0; x < width; x++)
			{
				if (a[row + x] != b[row + x])
				{
					if (x < minX)
					{
						minX = x;
					}
					if (x > maxX)
					{
						maxX = x;
					}
					if (y < minY)
					{
						minY = y;
					}
					maxY = y;
				}
			}
		}
		if (maxX < 0)
		{
			return new Rectangle(0, 0, 1, 1);
		}
		return new Rectangle(minX, minY, maxX - minX + 1, maxY - minY + 1);
	}

	private static BufferedImage crop(int[] pixels, int width, Rectangle area)
	{
		BufferedImage part = new BufferedImage(area.width, area.height, BufferedImage.TYPE_INT_RGB);
		part.setRGB(0, 0, area.width, area.height, pixels, area.y * width + area.x, width);
		return part;
	}

	private static IIOMetadataNode child(IIOMetadataNode root, String name)
	{
		for (int i = 0; i < root.getLength(); i++)
		{
			if (root.item(i).getNodeName().equals(name))
			{
				return (IIOMetadataNode) root.item(i);
			}
		}
		IIOMetadataNode node = new IIOMetadataNode(name);
		root.appendChild(node);
		return node;
	}
}

package com.deathrecap;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Line2D;
import java.awt.geom.Path2D;
import java.awt.geom.RoundRectangle2D;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Draws HP and prayer over the recap window: a filled HP line over a red low-HP band, a bar for every
 * hit (taller for bigger hits, stacked when they land together, numbered when there's room), a dot
 * for food and potions, a labelled line at the death or close call, a seconds axis and a legend.
 * Used by the side panel and the share card.
 */
final class HpGraph
{
	static final Color HP = new Color(0x4C, 0xC0, 0x4C);
	static final Color PRAYER = new Color(0x60, 0xB0, 0xFF);
	static final Color HIT = new Color(0xFF, 0x50, 0x50);
	static final Color FOOD = new Color(0xF0, 0xC0, 0x40);
	private static final Color BACKGROUND_TOP = new Color(0x24, 0x24, 0x24);
	private static final Color BACKGROUND_BOTTOM = new Color(0x16, 0x16, 0x16);
	private static final Color BORDER = new Color(0x40, 0x40, 0x40);
	private static final Color GRID = new Color(0xFF, 0xFF, 0xFF, 0x14);
	private static final Color LABEL = new Color(0xA0, 0xA0, 0xA0);
	private static final Color DANGER = new Color(0xFF, 0x30, 0x30, 0x22);
	/** The biggest hit's bar, as a share of the plot's height. */
	private static final double HIT_BAR_SHARE = 0.22;
	/** HP at or below this share of the maximum is shaded as dangerous. */
	private static final double DANGER_SHARE = 0.2;
	private static final double TICK_SECONDS = 0.6;
	private static final int[] AXIS_STEPS = {1, 2, 5, 10, 15, 30, 60};

	private HpGraph()
	{
	}

	static void paint(Graphics2D g, Rectangle area, DeathRecord record)
	{
		Graphics2D g2 = (Graphics2D) g.create();
		try
		{
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
			g2.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
			float scale = scale(area);
			float arc = 6 * scale;
			RoundRectangle2D frame = new RoundRectangle2D.Double(area.x, area.y, area.width - 1, area.height - 1, arc, arc);
			g2.setPaint(new GradientPaint(0, area.y, BACKGROUND_TOP, 0, area.y + area.height, BACKGROUND_BOTTOM));
			g2.fill(frame);

			FontMetrics fm = g2.getFontMetrics();
			Rectangle plot = plot(area, fm);
			List<TickSnapshot> ticks = sorted(record);
			if (!ticks.isEmpty())
			{
				g2.clip(frame);
				draw(g2, area, plot, fm, scale, record, ticks);
				g2.setClip(null);
			}
			g2.setStroke(new BasicStroke(1f));
			g2.setColor(BORDER);
			g2.draw(frame);
		}
		finally
		{
			g2.dispose();
		}
	}

	private static void draw(Graphics2D g2, Rectangle area, Rectangle plot, FontMetrics fm, float scale, DeathRecord record, List<TickSnapshot> ticks)
	{
		double[] range = range(record, ticks);
		int maxHp = 1;
		int maxPrayer = 1;
		for (TickSnapshot t : ticks)
		{
			maxHp = Math.max(maxHp, Math.max(t.getMaxHp(), t.getHp()));
			maxPrayer = Math.max(maxPrayer, t.getPrayer());
		}
		int maxHit = 1;
		for (RecapEvent e : record.getEvents())
		{
			if (e.isDamage())
			{
				maxHit = Math.max(maxHit, e.getAmount());
			}
		}
		int deathTick = record.getDeathTick();
		boolean labels = plot.y > area.y + fm.getHeight();

		// Low-HP band and quarter lines.
		double dangerY = y(maxHp * DANGER_SHARE, maxHp, plot);
		g2.setColor(DANGER);
		g2.fill(new Rectangle.Double(area.x, dangerY, area.width, plot.y + plot.height - dangerY));
		g2.setStroke(new BasicStroke(1f));
		g2.setColor(GRID);
		for (int q = 1; q <= 4; q++)
		{
			double gy = y(maxHp * q / 4.0, maxHp, plot);
			g2.draw(new Line2D.Double(area.x, gy, area.x + area.width, gy));
		}

		// Seconds axis, counted from the death.
		double startSec = (range[0] - deathTick) * TICK_SECONDS;
		double endSec = (range[1] - deathTick) * TICK_SECONDS;
		int step = AXIS_STEPS[AXIS_STEPS.length - 1];
		for (int s : AXIS_STEPS)
		{
			if (plot.width * s / Math.max(0.1, endSec - startSec) >= fm.stringWidth("-00s") * 1.8)
			{
				step = s;
				break;
			}
		}
		for (int s = (int) Math.ceil(startSec / step) * step; s <= endSec; s += step)
		{
			double gx = x(deathTick + s / TICK_SECONDS, range, plot);
			g2.setColor(GRID);
			g2.draw(new Line2D.Double(gx, plot.y, gx, plot.y + plot.height));
			if (labels)
			{
				String text = s == 0 ? "0s" : (s > 0 ? "+" : "") + s + "s";
				int tx = (int) Math.round(gx - fm.stringWidth(text) / 2.0);
				tx = Math.max(area.x + 2, Math.min(area.x + area.width - 2 - fm.stringWidth(text), tx));
				g2.setColor(LABEL);
				g2.drawString(text, tx, plot.y + plot.height + Math.round(2 * scale) + fm.getAscent());
			}
		}

		// HP area, prayer line, HP line.
		Path2D hp = line(ticks, range, plot, maxHp, false);
		Path2D fill = new Path2D.Double(hp);
		fill.lineTo(x(ticks.get(ticks.size() - 1).getTick(), range, plot), plot.y + plot.height);
		fill.lineTo(x(ticks.get(0).getTick(), range, plot), plot.y + plot.height);
		fill.closePath();
		g2.setPaint(new GradientPaint(0, plot.y, alpha(HP, 0x70), 0, plot.y + plot.height, alpha(HP, 0x10)));
		g2.fill(fill);
		g2.setStroke(new BasicStroke(1f * scale, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g2.setColor(alpha(PRAYER, 0x90));
		g2.draw(line(ticks, range, plot, maxPrayer, true));
		g2.setStroke(new BasicStroke(2f * scale, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g2.setColor(HP);
		g2.draw(hp);
		// Each drop in HP drawn in red and each rise in yellow, so damage and healing stand out on the line.
		g2.setStroke(new BasicStroke(2.5f * scale, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		for (int i = 1; i < ticks.size(); i++)
		{
			int before = ticks.get(i - 1).getHp();
			int after = ticks.get(i).getHp();
			if (before != after)
			{
				double sx = x(ticks.get(i).getTick(), range, plot);
				g2.setColor(after < before ? HIT : FOOD);
				g2.draw(new Line2D.Double(sx, y(before, maxHp, plot), sx, y(after, maxHp, plot)));
			}
		}

		// Hits, stacked when several land on one tick, numbered when there's room.
		List<RecapEvent> events = new ArrayList<>(record.getEvents());
		events.sort(Comparator.comparingInt(RecapEvent::getTick));
		Map<Integer, Double> stacked = new HashMap<>();
		double barWidth = Math.max(2, 3 * scale);
		double labelRight = Double.NEGATIVE_INFINITY;
		RecapEvent blow = !record.isDeath() ? null : killingBlow(events, deathTick);
		for (RecapEvent e : events)
		{
			if (!e.isDamage())
			{
				continue;
			}
			double ex = x(e.getTick(), range, plot);
			double h = Math.max(2, (double) e.getAmount() / maxHit * plot.height * HIT_BAR_SHARE);
			double base = stacked.getOrDefault(e.getTick(), 0.0);
			stacked.put(e.getTick(), base + h + 1);
			double top = plot.y + plot.height - base - h;
			Color c = e.getType() == RecapEvent.Type.HIT ? HIT : DeathRecapPanel.DOT;
			g2.setColor(e == blow ? c.brighter() : alpha(c, 0xB0));
			g2.fill(new RoundRectangle2D.Double(ex - barWidth / 2, top, barWidth, h, barWidth / 2, barWidth / 2));
			if (e == blow)
			{
				g2.setStroke(new BasicStroke(1f));
				g2.setColor(Color.WHITE);
				g2.draw(new RoundRectangle2D.Double(ex - barWidth / 2 - 1, top - 1, barWidth + 2, h + 2, barWidth / 2, barWidth / 2));
			}
			String n = String.valueOf(e.getAmount());
			int nw = fm.stringWidth(n);
			// Kept inside the plot, so the killing blow at the right edge isn't cut off.
			double lx = Math.min(ex - nw / 2.0, plot.x + plot.width - nw - 2 * scale);
			double ly = top - 2 * scale;
			if (labels && lx > labelRight + 2 * scale && ly - fm.getAscent() > plot.y)
			{
				// A dark outline keeps the number readable where it crosses the HP line.
				float o = Math.max(1, scale);
				g2.setColor(new Color(0, 0, 0, 0xC0));
				for (int d = 0; d < 4; d++)
				{
					g2.drawString(n, (float) lx + (d == 0 ? -o : d == 1 ? o : 0), (float) ly + (d == 2 ? -o : d == 3 ? o : 0));
				}
				g2.setColor(e == blow ? Color.WHITE : alpha(c, 0xE0));
				g2.drawString(n, (float) lx, (float) ly);
				labelRight = lx + nw;
			}
		}

		// Food and potions: a dot at the top with a faint line down.
		float r = 3.5f * scale;
		for (RecapEvent e : events)
		{
			if (e.getType() != RecapEvent.Type.EAT && e.getType() != RecapEvent.Type.DRINK)
			{
				continue;
			}
			double ex = x(e.getTick(), range, plot);
			g2.setStroke(new BasicStroke(1f));
			g2.setColor(alpha(FOOD, 0x50));
			g2.draw(new Line2D.Double(ex, plot.y + r * 2, ex, plot.y + plot.height));
			g2.setColor(FOOD);
			g2.fill(new Ellipse2D.Double(ex - r, plot.y, r * 2, r * 2));
			g2.setColor(BACKGROUND_BOTTOM);
			g2.draw(new Ellipse2D.Double(ex - r, plot.y, r * 2, r * 2));
		}

		// The death or low point.
		double dx = x(deathTick, range, plot);
		Color marker = record.isCloseCall() ? FOOD : record.isClip() ? PRAYER : Color.WHITE;
		g2.setStroke(new BasicStroke(scale, BasicStroke.CAP_BUTT, BasicStroke.JOIN_MITER, 10f, new float[]{4 * scale, 3 * scale}, 0f));
		g2.setColor(marker);
		g2.draw(new Line2D.Double(dx, plot.y, dx, plot.y + plot.height));
		TickSnapshot at = at(ticks, deathTick);
		double py = y(at.getHp(), maxHp, plot);
		g2.setStroke(new BasicStroke(1.5f * scale));
		g2.setColor(marker);
		g2.fill(new Ellipse2D.Double(dx - r, py - r, r * 2, r * 2));
		g2.setColor(BACKGROUND_BOTTOM);
		g2.draw(new Ellipse2D.Double(dx - r, py - r, r * 2, r * 2));

		if (labels)
		{
			int pad = Math.round(4 * scale);
			int baseline = area.y + pad + fm.getAscent();
			String tag = record.isCloseCall() ? "Low point " + at.getHp() + " HP" : record.isClip() ? "Clip saved" : "Death";
			int tw = fm.stringWidth(tag);
			int tx = dx + pad + tw <= area.x + area.width - pad ? (int) dx + pad : (int) dx - pad - tw;
			g2.setColor(marker);
			g2.drawString(tag, tx, baseline);
			legend(g2, fm, area.x + pad, baseline, tx - pad, scale, maxHp);
		}
	}

	/** Colour swatches with names along the top, as many as fit before {@code right}. */
	private static void legend(Graphics2D g2, FontMetrics fm, int x, int baseline, int right, float scale, int maxHp)
	{
		String[] names = {"HP (max " + maxHp + ")", "Prayer", "Hit", "Food"};
		Color[] colours = {HP, PRAYER, HIT, FOOD};
		int swatch = Math.max(6, Math.round(fm.getAscent() * 0.7f));
		int gap = Math.round(8 * scale);
		for (int i = 0; i < names.length; i++)
		{
			int w = swatch + Math.round(3 * scale) + fm.stringWidth(names[i]);
			if (x + w > right)
			{
				return;
			}
			g2.setColor(colours[i]);
			g2.fill(new RoundRectangle2D.Double(x, baseline - swatch, swatch, swatch, swatch / 2.0, swatch / 2.0));
			g2.setColor(LABEL);
			g2.drawString(names[i], x + swatch + Math.round(3 * scale), baseline);
			x += w + gap;
		}
	}

	/** The snapshot shown at {@code px} in a graph painted into {@code area} with {@code fm}, for tooltips. */
	static TickSnapshot at(DeathRecord record, int px, Rectangle area, FontMetrics fm)
	{
		List<TickSnapshot> ticks = sorted(record);
		if (ticks.isEmpty() || area.width <= 0)
		{
			return null;
		}
		Rectangle plot = plot(area, fm);
		double[] range = range(record, ticks);
		double tick = range[0] + (double) (px - plot.x) * (range[1] - range[0]) / Math.max(1, plot.width) + 1e-9;
		return at(ticks, tick);
	}

	private static TickSnapshot at(List<TickSnapshot> ticks, double tick)
	{
		TickSnapshot found = ticks.get(0);
		for (TickSnapshot t : ticks)
		{
			if (t.getTick() > tick)
			{
				break;
			}
			found = t;
		}
		return found;
	}

	private static RecapEvent killingBlow(List<RecapEvent> sorted, int deathTick)
	{
		RecapEvent blow = null;
		for (RecapEvent e : sorted)
		{
			if (e.isDamage() && e.getTick() <= deathTick)
			{
				blow = e;
			}
		}
		return blow;
	}

	private static float scale(Rectangle area)
	{
		return Math.max(1f, Math.min(area.width / 320f, area.height / 110f));
	}

	/** Where the lines go: inside {@code area}, below the legend and above the axis when they fit. */
	private static Rectangle plot(Rectangle area, FontMetrics fm)
	{
		int pad = Math.round(4 * scale(area));
		int text = fm.getHeight();
		int top = area.y + pad + text + pad;
		int bottom = area.y + area.height - pad - text;
		if (bottom - top < text * 2)
		{
			return new Rectangle(area.x + pad, area.y + pad, Math.max(1, area.width - pad * 2), Math.max(1, area.height - pad * 2));
		}
		return new Rectangle(area.x + pad, top, area.width - pad * 2, bottom - top);
	}

	private static List<TickSnapshot> sorted(DeathRecord record)
	{
		List<TickSnapshot> ticks = new ArrayList<>(record.getTicks());
		ticks.sort(Comparator.comparingInt(TickSnapshot::getTick));
		return ticks;
	}

	/** First and last tick on the x axis. */
	private static double[] range(DeathRecord record, List<TickSnapshot> ticks)
	{
		int min = ticks.get(0).getTick();
		int max = Math.max(ticks.get(ticks.size() - 1).getTick(), record.getDeathTick());
		for (RecapEvent e : record.getEvents())
		{
			min = Math.min(min, e.getTick());
			max = Math.max(max, e.getTick());
		}
		return new double[]{min, max > min ? max : min + 1};
	}

	private static double x(double tick, double[] range, Rectangle plot)
	{
		return plot.x + (tick - range[0]) * plot.width / (range[1] - range[0]);
	}

	private static double y(double value, int max, Rectangle plot)
	{
		return plot.y + plot.height - plot.height * Math.max(0, Math.min(1.0, value / max));
	}

	/** A step line: each tick's value holds until the next tick. */
	private static Path2D line(List<TickSnapshot> ticks, double[] range, Rectangle plot, int max, boolean prayer)
	{
		Path2D path = new Path2D.Double();
		for (int i = 0; i < ticks.size(); i++)
		{
			TickSnapshot t = ticks.get(i);
			double y = y(prayer ? t.getPrayer() : t.getHp(), max, plot);
			double x = x(t.getTick(), range, plot);
			if (i == 0)
			{
				path.moveTo(x, y);
			}
			else
			{
				path.lineTo(x, path.getCurrentPoint().getY());
				path.lineTo(x, y);
			}
		}
		return path;
	}

	private static Color alpha(Color c, int alpha)
	{
		return new Color(c.getRed(), c.getGreen(), c.getBlue(), alpha);
	}
}

package com.deathrecap;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import lombok.Value;

/**
 * Estimates which items a death keeps and which are at risk, using the standard rules: the three most
 * valuable items are kept, none when skulled, and Protect Item keeps one more. Each item in a stack
 * counts on its own, so a stack can be split between kept and at risk. Ties go to the item worn or
 * carried first. Ultimate Ironmen, safe deaths and some minigames follow other rules.
 */
final class ItemsOnDeath
{
	@Value
	static class Result
	{
		List<DeathState.ItemStack> kept;
		List<DeathState.ItemStack> atRisk;
		long keptValue;
		long riskValue;
	}

	private ItemsOnDeath()
	{
	}

	static int keepCount(boolean skulled, boolean protectItem)
	{
		return (skulled ? 0 : 3) + (protectItem ? 1 : 0);
	}

	static Result compute(DeathState state)
	{
		List<DeathState.ItemStack> all = new ArrayList<>(state.getEquipment());
		all.addAll(state.getInventory());
		// A stable sort keeps worn items ahead of carried ones, in slot order, when values tie.
		all.sort(Comparator.comparingLong(DeathState.ItemStack::getPrice).reversed());

		int keep = keepCount(state.isSkulled(), state.isProtectItem());
		Map<Integer, DeathState.ItemStack> kept = new LinkedHashMap<>();
		Map<Integer, DeathState.ItemStack> atRisk = new LinkedHashMap<>();
		long keptValue = 0;
		long riskValue = 0;
		for (DeathState.ItemStack s : all)
		{
			int take = Math.min(keep, s.getQuantity());
			keep -= take;
			if (take > 0)
			{
				merge(kept, s, take);
				keptValue += take * s.getPrice();
			}
			int rest = s.getQuantity() - take;
			if (rest > 0)
			{
				// Unstackable items, like five Jangerberries, are listed once with their total.
				merge(atRisk, s, rest);
				riskValue += rest * s.getPrice();
			}
		}
		List<DeathState.ItemStack> risk = new ArrayList<>(atRisk.values());
		risk.sort(Comparator.comparingLong((DeathState.ItemStack s) -> s.getPrice() * s.getQuantity()).reversed());
		return new Result(new ArrayList<>(kept.values()), risk, keptValue, riskValue);
	}

	private static void merge(Map<Integer, DeathState.ItemStack> into, DeathState.ItemStack s, int quantity)
	{
		DeathState.ItemStack k = into.get(s.getId());
		if (k != null)
		{
			k.setQuantity(k.getQuantity() + quantity);
		}
		else
		{
			into.put(s.getId(), new DeathState.ItemStack(s.getId(), s.getName(), quantity, s.getPrice()));
		}
	}

	/** 1234 -> "1,234", 1_234_567 -> "1.23M", 12_345_678_901 -> "12.3B". */
	static String gp(long value)
	{
		if (value >= 1_000_000_000L)
		{
			return trim(value / 1e9) + "B";
		}
		if (value >= 10_000_000L)
		{
			return trim(value / 1e6) + "M";
		}
		if (value >= 1_000_000L)
		{
			return String.format(Locale.ROOT, "%.2fM", value / 1e6);
		}
		return String.format(Locale.ROOT, "%,d", value);
	}

	private static String trim(double v)
	{
		return String.format(Locale.ROOT, v >= 100 ? "%.0f" : "%.1f", v);
	}
}

package com.deathrecap;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Optional;
import java.util.Set;
import java.util.TreeMap;
import java.util.stream.Collectors;
import lombok.Value;

/**
 * Turns a raw {@link DeathRecord} into a killing blow, a damage breakdown and plain-language findings.
 * Everything here is a statement of what happened; it never suggests what to do in combat.
 */
public final class RecapAnalyzer
{
	public static final double TICK_SECONDS = 0.6;

	@Value
	public static class SourceDamage
	{
		String source;
		int damage;
		int hits;
	}

	@Value
	public static class Summary
	{
		String killer;
		RecapEvent killingBlow;
		int totalDamage;
		List<SourceDamage> bySource;
		RecapEvent biggestHit;
		List<String> findings;
	}

	private RecapAnalyzer()
	{
	}

	public static Summary analyze(DeathRecord record)
	{
		final int deathTick = record.getDeathTick();
		final List<RecapEvent> events = new ArrayList<>(record.getEvents());
		events.sort(Comparator.comparingInt(RecapEvent::getTick));
		final List<TickSnapshot> ticks = new ArrayList<>(record.getTicks());
		ticks.sort(Comparator.comparingInt(TickSnapshot::getTick));

		final List<RecapEvent> damage = events.stream().filter(RecapEvent::isDamage).collect(Collectors.toList());
		if (record.isCloseCall())
		{
			return closeCall(record, events, ticks, damage);
		}
		if (record.isClip())
		{
			return clip(record, events, ticks, damage);
		}
		final RecapEvent killingBlow = damage.isEmpty() ? null : damage.get(damage.size() - 1);
		final String killer = killerOf(damage);

		int total = damage.stream().mapToInt(RecapEvent::getAmount).sum();
		RecapEvent biggest = biggest(damage);
		final List<SourceDamage> bySource = bySource(damage);

		final List<String> findings = new ArrayList<>();
		if (killingBlow != null)
		{
			TickSnapshot before = snapshotAt(ticks, killingBlow.getTick() - 1);
			findings.add(String.format("Killing blow: %d from %s%s%s.%s", killingBlow.getAmount(), label(record, killingBlow.getSource()),
				killingBlow.getWeapon() != null ? " with " + killingBlow.getWeapon() : "",
				killingBlow.getDetail() != null ? " (" + killingBlow.getDetail() + ")" : "",
				before != null && before.getHp() > 0 ? String.format(" You had %d HP.", before.getHp()) : ""));
		}
		else
		{
			findings.add("No damage was recorded before this death.");
		}

		if (total > 0)
		{
			int firstDamageTick = damage.get(0).getTick();
			int span = deathTick - firstDamageTick + 1;
			StringBuilder sb = new StringBuilder(String.format("You took %d damage in %s", total, seconds(span)));
			if (span >= 3)
			{
				sb.append(String.format(Locale.ROOT, " (%.1f per second)", total / (span * TICK_SECONDS)));
			}
			if (bySource.size() > 1)
			{
				sb.append(": ");
				int shown = Math.min(3, bySource.size());
				for (int i = 0; i < shown; i++)
				{
					SourceDamage s = bySource.get(i);
					if (i > 0)
					{
						sb.append(", ");
					}
					sb.append(String.format("%s %d (%d%%)", s.getSource(), s.getDamage(), Math.round(100.0 * s.getDamage() / total)));
				}
			}
			sb.append('.');
			findings.add(sb.toString());
		}

		if (biggest != null && biggest != killingBlow)
		{
			findings.add(String.format("Biggest hit: %d from %s, %s before death.", biggest.getAmount(), biggest.getSource(),
				seconds(deathTick - biggest.getTick())));
		}

		burst(damage, deathTick, "death").ifPresent(findings::add);
		playerFindings(record, events, findings);
		hpFindings(ticks, events, deathTick, findings);
		prayerFindings(ticks, events, killingBlow, deathTick, findings);
		suppliesFinding(record.getState(), findings);

		int dot = damage.stream().filter(e -> e.getType() == RecapEvent.Type.DAMAGE_OVER_TIME).mapToInt(RecapEvent::getAmount).sum();
		if (dot > 0)
		{
			Set<String> kinds = damage.stream().filter(e -> e.getType() == RecapEvent.Type.DAMAGE_OVER_TIME)
				.map(RecapEvent::getSource).collect(Collectors.toCollection(LinkedHashSet::new));
			findings.add(String.format("%s dealt %d damage over time.", String.join(" and ", kinds), dot));
		}

		return new Summary(killer, killingBlow, total, bySource, biggest, findings);
	}

	/**
	 * Findings for a close call. The record's death tick is when HP first fell below the close call
	 * threshold; the record runs on until the fight calmed down.
	 */
	private static Summary closeCall(DeathRecord record, List<RecapEvent> events, List<TickSnapshot> ticks, List<RecapEvent> damage)
	{
		final int lowTick = record.getDeathTick();
		final List<RecapEvent> before = damage.stream().filter(e -> e.getTick() <= lowTick).collect(Collectors.toList());
		// The hit that took HP low: the last direct hit up to the threshold tick.
		RecapEvent low = null;
		for (RecapEvent e : before)
		{
			if (e.getType() == RecapEvent.Type.HIT)
			{
				low = e;
			}
		}
		final String killer = killerOf(before.isEmpty() ? damage : before);
		int total = damage.stream().mapToInt(RecapEvent::getAmount).sum();
		RecapEvent biggest = biggest(damage);
		List<SourceDamage> bySource = bySource(damage);
		List<String> findings = new ArrayList<>();

		TickSnapshot lowest = null;
		int maxHp = 1;
		for (TickSnapshot t : ticks)
		{
			maxHp = Math.max(maxHp, t.getMaxHp());
			if (t.getHp() > 0 && (lowest == null || t.getHp() < lowest.getHp()))
			{
				lowest = t;
			}
		}
		if (lowest != null)
		{
			findings.add(String.format("HP fell to %d of %d (%d%%) and you survived.", lowest.getHp(), maxHp,
				Math.round(100.0 * lowest.getHp() / maxHp)));
		}
		if (low != null)
		{
			findings.add(String.format("The hit that took you low: %d from %s%s%s.", low.getAmount(), label(record, low.getSource()),
				low.getWeapon() != null ? " with " + low.getWeapon() : "", low.getDetail() != null ? " (" + low.getDetail() + ")" : ""));
			TickSnapshot at = snapshotAt(ticks, low.getTick() - 1);
			if (at != null && low.getType() == RecapEvent.Type.HIT)
			{
				findings.add(at.getProtection() != null
					? at.getProtection() + " was active when it landed."
					: "No protection prayer was active when it landed.");
			}
		}
		if (total > 0)
		{
			findings.add(String.format("You took %d damage in %s.", total,
				seconds(damage.get(damage.size() - 1).getTick() - damage.get(0).getTick() + 1)));
		}
		if (biggest != null && biggest != low)
		{
			findings.add(String.format("Biggest hit: %d from %s.", biggest.getAmount(), biggest.getSource()));
		}
		burst(damage, lowTick, "HP dropped low").ifPresent(findings::add);
		playerFindings(record, events, findings);

		List<RecapEvent> after = events.stream()
			.filter(e -> e.getTick() >= lowTick && (e.getType() == RecapEvent.Type.EAT || e.getType() == RecapEvent.Type.DRINK))
			.collect(Collectors.toList());
		if (after.isEmpty())
		{
			findings.add("You didn't eat or drink after dropping low.");
		}
		else
		{
			RecapEvent first = after.get(0);
			findings.add(String.format("You ate or drank %d time%s after dropping low; the first was %s, %s later.", after.size(),
				after.size() == 1 ? "" : "s", first.getSource(), seconds(first.getTick() - lowTick)));
		}
		return new Summary(killer, low, total, bySource, biggest, findings);
	}

	/**
	 * Findings for a clip saved with the hotkey. The record's death tick is the key press; nothing died.
	 */
	private static Summary clip(DeathRecord record, List<RecapEvent> events, List<TickSnapshot> ticks, List<RecapEvent> damage)
	{
		final int pressTick = record.getDeathTick();
		final String killer = damage.isEmpty() ? "Nothing" : killerOf(damage);
		int total = damage.stream().mapToInt(RecapEvent::getAmount).sum();
		RecapEvent biggest = biggest(damage);
		List<SourceDamage> bySource = bySource(damage);
		List<String> findings = new ArrayList<>();
		if (total > 0)
		{
			StringBuilder sb = new StringBuilder(String.format("You took %d damage in %s", total,
				seconds(damage.get(damage.size() - 1).getTick() - damage.get(0).getTick() + 1)));
			if (bySource.size() > 1)
			{
				sb.append(": ");
				int shown = Math.min(3, bySource.size());
				for (int i = 0; i < shown; i++)
				{
					SourceDamage s = bySource.get(i);
					sb.append(i > 0 ? ", " : "").append(String.format("%s %d", s.getSource(), s.getDamage()));
				}
			}
			findings.add(sb.append('.').toString());
		}
		else
		{
			findings.add("You took no damage in this clip.");
		}
		if (biggest != null)
		{
			findings.add(String.format("Biggest hit: %d from %s, %s before the clip was saved.", biggest.getAmount(),
				biggest.getSource(), seconds(pressTick - biggest.getTick())));
		}
		burst(damage, pressTick, "the clip was saved").ifPresent(findings::add);
		playerFindings(record, events, findings);
		if (!ticks.isEmpty())
		{
			TickSnapshot first = ticks.get(0);
			TickSnapshot last = ticks.get(ticks.size() - 1);
			int lowest = ticks.stream().mapToInt(TickSnapshot::getHp).min().orElse(first.getHp());
			findings.add(String.format("HP went from %d to %d; the lowest was %d.", first.getHp(), last.getHp(), lowest));
		}
		long eats = events.stream().filter(e -> e.getType() == RecapEvent.Type.EAT || e.getType() == RecapEvent.Type.DRINK).count();
		if (eats > 0)
		{
			findings.add(String.format("You ate or drank %d time%s.", eats, eats == 1 ? "" : "s"));
		}
		return new Summary(killer, null, total, bySource, biggest, findings);
	}

	/** "Zezima (level 126)" when the attacker's combat level was recorded, otherwise just the name. */
	public static String label(DeathRecord record, String name)
	{
		Attacker a = record.attacker(name);
		return a != null && a.getCombatLevel() > 0 ? name + " (level " + a.getCombatLevel() + ")" : name;
	}

	/** The weapons a player attacker was seen holding, in the order they were first seen. */
	public static List<String> weapons(DeathRecord record, String name)
	{
		return record.getEvents().stream()
			.sorted(Comparator.comparingInt(RecapEvent::getTick))
			.filter(e -> name.equals(e.getSource()) && e.getWeapon() != null)
			.map(RecapEvent::getWeapon)
			.distinct()
			.collect(Collectors.toList());
	}

	/** True when another player dealt damage in this recap. */
	public static boolean isPvp(DeathRecord record)
	{
		return record.getAttackers() != null && record.getAttackers().stream()
			.anyMatch(a -> a.isPlayer() && record.getEvents().stream().anyMatch(e -> e.isDamage() && a.getName().equals(e.getSource())));
	}

	/** For each player that attacked: their hits, zeros, biggest hit and the weapons they used. */
	private static void playerFindings(DeathRecord record, List<RecapEvent> events, List<String> findings)
	{
		if (record.getAttackers() == null)
		{
			return;
		}
		List<Attacker> players = record.getAttackers().stream().filter(Attacker::isPlayer).collect(Collectors.toList());
		List<String> lines = new ArrayList<>();
		for (Attacker p : players)
		{
			List<RecapEvent> hits = events.stream()
				.filter(e -> p.getName().equals(e.getSource()) && (e.getType() == RecapEvent.Type.HIT || e.getType() == RecapEvent.Type.BLOCK))
				.collect(Collectors.toList());
			if (hits.isEmpty())
			{
				continue;
			}
			long zeros = hits.stream().filter(e -> e.getAmount() == 0).count();
			int max = hits.stream().mapToInt(RecapEvent::getAmount).max().orElse(0);
			List<String> used = weapons(record, p.getName());
			StringBuilder sb = new StringBuilder(label(record, p.getName()));
			sb.append(String.format(" hit you %d time%s", hits.size(), hits.size() == 1 ? "" : "s"));
			if (zeros > 0)
			{
				sb.append(String.format(" (%d for 0)", zeros));
			}
			sb.append(String.format(", up to %d", max));
			if (!used.isEmpty())
			{
				sb.append(", using ").append(joinAnd(used));
			}
			lines.add(sb.append('.').toString());
		}
		if (lines.size() > 1)
		{
			findings.add(String.format("%d players attacked you.", lines.size()));
		}
		findings.addAll(lines);
	}

	static String joinAnd(List<String> parts)
	{
		if (parts.size() <= 1)
		{
			return String.join("", parts);
		}
		return String.join(", ", parts.subList(0, parts.size() - 1)) + " and " + parts.get(parts.size() - 1);
	}

	/** HP regained between snapshots: food, potions, heals and regeneration. */
	static int healed(List<TickSnapshot> ticks)
	{
		int healed = 0;
		for (int i = 1; i < ticks.size(); i++)
		{
			healed += Math.max(0, ticks.get(i).getHp() - ticks.get(i - 1).getHp());
		}
		return healed;
	}

	/** What food and potions were still in the inventory at death; skipped for recaps from before this was recorded. */
	static void suppliesFinding(DeathState state, List<String> findings)
	{
		if (state == null || state.getFood() == null || state.getPotions() == null)
		{
			return;
		}
		List<DeathState.ItemStack> all = new ArrayList<>(state.getFood());
		all.addAll(state.getPotions());
		if (all.isEmpty())
		{
			findings.add("You had no food or potions left.");
			return;
		}
		List<String> names = new ArrayList<>();
		for (int i = 0; i < Math.min(3, all.size()); i++)
		{
			DeathState.ItemStack s = all.get(i);
			names.add(s.getQuantity() + " x " + s.getName());
		}
		String more = all.size() > 3 ? String.format(" (+%d more)", all.size() - 3) : "";
		String what = state.getFood().isEmpty() ? "potions" : state.getPotions().isEmpty() ? "food" : "food and potions";
		findings.add(String.format("You died with %s left: %s%s.", what, String.join(", ", names), more));
	}

	private static RecapEvent biggest(List<RecapEvent> damage)
	{
		RecapEvent biggest = null;
		for (RecapEvent e : damage)
		{
			if (biggest == null || e.getAmount() > biggest.getAmount())
			{
				biggest = e;
			}
		}
		return biggest;
	}

	private static List<SourceDamage> bySource(List<RecapEvent> damage)
	{
		final Map<String, int[]> totals = new LinkedHashMap<>();
		for (RecapEvent e : damage)
		{
			int[] t = totals.computeIfAbsent(e.getSource(), k -> new int[2]);
			t[0] += e.getAmount();
			t[1]++;
		}
		return totals.entrySet().stream()
			.map(en -> new SourceDamage(en.getKey(), en.getValue()[0], en.getValue()[1]))
			.sorted(Comparator.comparingInt(SourceDamage::getDamage).reversed())
			.collect(Collectors.toList());
	}

	/**
	 * The killer is whoever dealt the last direct hit; damage over time only counts when nothing else hit.
	 */
	static String killerOf(List<RecapEvent> damage)
	{
		for (int i = damage.size() - 1; i >= 0; i--)
		{
			RecapEvent e = damage.get(i);
			if (e.getType() == RecapEvent.Type.HIT && !"Unknown".equals(e.getSource()))
			{
				return e.getSource();
			}
		}
		return damage.isEmpty() ? "Unknown" : damage.get(damage.size() - 1).getSource();
	}

	private static Optional<String> burst(List<RecapEvent> damage, int deathTick, String moment)
	{
		Map<Integer, List<RecapEvent>> byTick = new TreeMap<>();
		for (RecapEvent e : damage)
		{
			byTick.computeIfAbsent(e.getTick(), k -> new ArrayList<>()).add(e);
		}
		List<RecapEvent> best = null;
		int bestSum = 0;
		for (List<RecapEvent> group : byTick.values())
		{
			int sum = group.stream().mapToInt(RecapEvent::getAmount).sum();
			if (group.size() > 1 && sum > bestSum)
			{
				best = group;
				bestSum = sum;
			}
		}
		if (best == null)
		{
			return Optional.empty();
		}
		Set<String> who = best.stream().map(RecapEvent::getSource).collect(Collectors.toCollection(LinkedHashSet::new));
		int before = deathTick - best.get(0).getTick();
		String when = before >= 0 ? seconds(before) + " before " + moment : seconds(-before) + " after " + moment;
		return Optional.of(String.format("Biggest single-tick burst: %d damage from %d hits (%s), %s.",
			bestSum, best.size(), String.join(", ", who), when));
	}

	private static void hpFindings(List<TickSnapshot> ticks, List<RecapEvent> events, int deathTick, List<String> findings)
	{
		if (ticks.isEmpty())
		{
			return;
		}
		TickSnapshot first = ticks.get(0);
		int maxHp = Math.max(1, first.getMaxHp());
		int peak = ticks.stream().mapToInt(TickSnapshot::getHp).max().orElse(0);
		if (peak > 0)
		{
			int peakTick = 0;
			for (TickSnapshot t : ticks)
			{
				if (t.getHp() == peak)
				{
					peakTick = t.getTick();
				}
			}
			findings.add(String.format("HP went from %d to 0 in %s.", peak, seconds(deathTick - peakTick)));
		}

		List<RecapEvent> consumed = events.stream()
			.filter(e -> e.getType() == RecapEvent.Type.EAT || e.getType() == RecapEvent.Type.DRINK)
			.collect(Collectors.toList());
		int lowSince = sinceBelow(ticks, maxHp * 0.25);
		int halfSince = sinceBelow(ticks, maxHp * 0.5);
		boolean noFood = halfSince >= 0 && deathTick - halfSince >= 2 && consumed.stream().noneMatch(e -> e.getTick() >= halfSince);
		// When HP was already under a quarter for as long as it was under half, one line says both.
		boolean sameSpan = noFood && lowSince == halfSince;
		if (lowSince >= 0 && deathTick - lowSince >= 2)
		{
			findings.add(String.format("You were at or below 25%% HP for the last %s%s.", seconds(deathTick - lowSince),
				sameSpan ? " and didn't eat or drink" : ""));
		}

		if (noFood)
		{
			if (!sameSpan)
			{
				findings.add(String.format("You were below 50%% HP for the last %s and didn't eat or drink.", seconds(deathTick - halfSince)));
			}
		}
		else if (consumed.isEmpty())
		{
			findings.add(String.format("You didn't eat or drink in the last %s.", seconds(deathTick - first.getTick())));
		}
		else
		{
			RecapEvent last = consumed.get(consumed.size() - 1);
			int healed = healed(ticks.stream().filter(t -> t.getTick() <= deathTick).collect(Collectors.toList()));
			findings.add(String.format("You ate or drank %d time%s%s; the last was %s, %s before death.", consumed.size(),
				consumed.size() == 1 ? "" : "s", healed > 0 ? " and healed " + healed + " HP" : "",
				last.getSource(), seconds(deathTick - last.getTick())));
		}
	}

	/**
	 * Returns the tick from which HP stayed at or below {@code threshold} until death, or -1.
	 */
	private static int sinceBelow(List<TickSnapshot> ticks, double threshold)
	{
		int since = -1;
		for (int i = ticks.size() - 1; i >= 0; i--)
		{
			if (ticks.get(i).getHp() > threshold)
			{
				break;
			}
			since = ticks.get(i).getTick();
		}
		return since;
	}

	private static void prayerFindings(List<TickSnapshot> ticks, List<RecapEvent> events, RecapEvent killingBlow, int deathTick, List<String> findings)
	{
		if (killingBlow != null && killingBlow.getType() == RecapEvent.Type.HIT)
		{
			TickSnapshot at = snapshotAt(ticks, killingBlow.getTick() - 1);
			if (at != null)
			{
				findings.add(at.getProtection() != null
					? at.getProtection() + " was active when the killing blow landed."
					: "No protection prayer was active when the killing blow landed.");
			}
		}

		events.stream()
			.filter(e -> e.getType() == RecapEvent.Type.PRAYER_EMPTY)
			.reduce((a, b) -> b)
			.ifPresent(e -> findings.add(String.format("Prayer ran out %s before death.", seconds(deathTick - e.getTick()))));
	}

	/**
	 * Latest snapshot at or before {@code tick}; prayers are read at the end of the tick, so the
	 * state the hit landed against is the previous tick's.
	 */
	private static TickSnapshot snapshotAt(List<TickSnapshot> ticks, int tick)
	{
		TickSnapshot found = null;
		for (TickSnapshot t : ticks)
		{
			if (t.getTick() > tick)
			{
				break;
			}
			found = t;
		}
		return found != null ? found : (ticks.isEmpty() ? null : ticks.get(0));
	}

	public static String seconds(int ticks)
	{
		return String.format(Locale.ROOT, "%.1fs", Math.max(0, ticks) * TICK_SECONDS);
	}
}

package com.deathrecap;

import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

/**
 * Something that happened to or by the player in the moments before a death.
 */
@Data
@NoArgsConstructor
@AllArgsConstructor
public class RecapEvent
{
	public enum Type
	{
		/** Direct damage from an attacker. */
		HIT,
		/** Poison, venom, burn, bleed and other damage over time. */
		DAMAGE_OVER_TIME,
		/** A zero hitsplat. */
		BLOCK,
		HEAL,
		/** An attacker that was targeting the player started an animation. */
		ATTACK,
		/** A projectile was launched at the player. */
		PROJECTILE,
		EAT,
		DRINK,
		PRAYER_ON,
		PRAYER_OFF,
		PRAYER_EMPTY,
	}

	private int tick;
	private Type type;
	private int amount;
	/** Attacker, damage type, item or prayer name. */
	private String source;
	/** How the source was attributed, e.g. "projectile" or "melee range". May be null. */
	private String detail;
	/** The weapon a player attacker was holding, or null for NPCs and older recaps. */
	private String weapon;

	public RecapEvent(int tick, Type type, int amount, String source, String detail)
	{
		this(tick, type, amount, source, detail, null);
	}

	public boolean isDamage()
	{
		return (type == Type.HIT || type == Type.DAMAGE_OVER_TIME) && amount > 0;
	}
}

package com.deathrecap;

import java.text.SimpleDateFormat;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.Date;
import java.util.List;
import java.util.Locale;
import java.util.stream.Collectors;

/**
 * Plain-text rendering of recaps, shared by the panel, the clipboard export and chat.
 */
final class RecapText
{
	private RecapText()
	{
	}

	static String describe(RecapEvent e)
	{
		String detail = e.getDetail() != null ? " (" + e.getDetail() + ")" : "";
		switch (e.getType())
		{
			case HIT:
				return "Hit " + e.getAmount() + " from " + e.getSource() + detail;
			case DAMAGE_OVER_TIME:
				return e.getSource() + " " + e.getAmount();
			case BLOCK:
				return "Blocked a hit from " + e.getSource() + detail;
			case HEAL:
				return "Healed " + e.getAmount();
			case ATTACK:
				return e.getSource() + " attacked";
			case PROJECTILE:
				return e.getSource() + " launched a projectile";
			case EAT:
				return "Ate " + e.getSource();
			case DRINK:
				return "Drank " + e.getSource();
			case PRAYER_ON:
				return e.getSource() + " on";
			case PRAYER_OFF:
				return e.getSource() + " off";
			case PRAYER_EMPTY:
				return "Out of prayer";
			default:
				return e.getSource();
		}
	}

	static String offset(int tick, int deathTick)
	{
		if (tick == deathTick)
		{
			return "0.0s";
		}
		return tick > deathTick ? "+" + RecapAnalyzer.seconds(tick - deathTick) : "-" + RecapAnalyzer.seconds(deathTick - tick);
	}

	static String location(DeathRecord r)
	{
		int wild = wildernessLevel(r);
		return String.format("World %d, %s (%d, %d, %d)", r.getWorld(),
			wild > 0 ? "Wilderness level " + wild : "region " + r.getRegionId(), r.getX(), r.getY(), r.getPlane());
	}

	/** "World 330" or "World 330 · Wilderness 23". */
	static String place(DeathRecord r)
	{
		int wild = wildernessLevel(r);
		return "World " + r.getWorld() + (wild > 0 ? " · Wilderness " + wild : "");
	}

	/** The Wilderness level at the recap's location, or 0 outside the Wilderness. */
	static int wildernessLevel(DeathRecord r)
	{
		int x = r.getX();
		int y = r.getY();
		if (x < 2944 || x > 3391)
		{
			return 0;
		}
		if (y >= 3523 && y <= 3967)
		{
			return (y - 3520) / 8 + 1;
		}
		if (y >= 9920 && y <= 10367)
		{
			return (y - 9920) / 8 + 1;
		}
		return 0;
	}

	/** "Zezima (level 126) with Armadyl godsword", or just the name when nothing else is known. */
	static String killer(DeathRecord r, RecapAnalyzer.Summary s)
	{
		String weapon = killerWeapon(r, s);
		return RecapAnalyzer.label(r, s.getKiller()) + (weapon != null ? " with " + weapon : "");
	}

	/** The weapon the killer dealt the killing blow with, or last held; null for NPCs. */
	static String killerWeapon(DeathRecord r, RecapAnalyzer.Summary s)
	{
		String name = s.getKiller();
		String weapon = s.getKillingBlow() != null && name.equals(s.getKillingBlow().getSource()) ? s.getKillingBlow().getWeapon() : null;
		if (weapon == null)
		{
			List<String> used = RecapAnalyzer.weapons(r, name);
			weapon = used.isEmpty() ? null : used.get(used.size() - 1);
		}
		return weapon;
	}

	static String date(long timestamp)
	{
		return new SimpleDateFormat("MMM d, HH:mm").format(new Date(timestamp));
	}

	/** "killed by X", "close call against X" or "clip" (with who hit hardest, if anyone did). */
	static String headline(DeathRecord r, RecapAnalyzer.Summary s)
	{
		if (r.isClip())
		{
			return s.getTotalDamage() > 0 ? "clip, fighting " + killer(r, s) : "clip";
		}
		return (r.isCloseCall() ? "close call against " : "killed by ") + killer(r, s);
	}

	static String full(DeathRecord r, RecapAnalyzer.Summary s)
	{
		StringBuilder sb = new StringBuilder();
		sb.append("Death Recap: ").append(headline(r, s)).append('\n');
		sb.append(date(r.getTimestamp())).append(" - ").append(location(r)).append("\n\n");
		for (String f : s.getFindings())
		{
			sb.append("* ").append(f).append('\n');
		}
		DeathState state = r.getState();
		if (state != null)
		{
			sb.append(r.isCloseCall() ? "\nAt the low point:\n" : r.isClip() ? "\nWhen the clip was saved:\n" : "\nAt death:\n");
			for (String line : stateLines(state))
			{
				sb.append("  ").append(line).append('\n');
			}
			if (r.isDeath())
			{
				ItemsOnDeath.Result items = ItemsOnDeath.compute(state);
				sb.append(String.format("  Items at risk (estimate): %s gp; kept: %s gp%n",
					ItemsOnDeath.gp(items.getRiskValue()), ItemsOnDeath.gp(items.getKeptValue())));
			}
		}
		sb.append("\nTimeline:\n");
		List<RecapEvent> events = r.getEvents().stream()
			.sorted(Comparator.comparingInt(RecapEvent::getTick))
			.collect(Collectors.toList());
		for (RecapEvent e : events)
		{
			sb.append(String.format("%7s  %s%n", offset(e.getTick(), r.getDeathTick()), describe(e)));
		}
		return sb.toString();
	}

	/** " Lost about 1.2M gp (Abyssal whip, ...)." for chat, or "" when nothing was at risk or it's unknown. */
	static String lostSentence(DeathRecord r)
	{
		if (!r.isDeath() || r.getState() == null)
		{
			return "";
		}
		ItemsOnDeath.Result items = ItemsOnDeath.compute(r.getState());
		if (items.getAtRisk().isEmpty())
		{
			return " Nothing lost.";
		}
		String names = items.getAtRisk().stream().limit(3).map(RecapText::stack).collect(Collectors.joining(", "));
		return " Lost about " + ItemsOnDeath.gp(items.getRiskValue()) + " gp (" + names
			+ (items.getAtRisk().size() > 3 ? ", ..." : "") + ").";
	}

	/** "3 x Shark", or just the name for one. */
	static String stack(DeathState.ItemStack s)
	{
		return (s.getQuantity() > 1 ? String.format(Locale.ROOT, "%,d x ", s.getQuantity()) : "") + s.getName();
	}

	/** Weapon, specials, prayers and stats at the moment of death, one line each; empty parts are left out. */
	static List<String> stateLines(DeathState s)
	{
		List<String> lines = new ArrayList<>();
		if (s.getWeapon() != null)
		{
			lines.add("Weapon: " + s.getWeapon() + (s.getAttackStyle() != null ? " (" + s.getAttackStyle() + ")" : ""));
		}
		lines.add(String.format("Special attack %d%%, run energy %d%%%s%s", s.getSpecEnergy(), s.getRunEnergy(),
			s.isSkulled() ? ", skulled" : "", s.isProtectItem() ? ", Protect Item on" : ""));
		if (s.getPrayers() != null && !s.getPrayers().isEmpty())
		{
			lines.add("Prayers: " + String.join(", ", s.getPrayers()));
		}
		if (s.getStats() != null && !s.getStats().isEmpty())
		{
			lines.add("Stats: " + s.getStats().stream()
				.map(st -> st.getSkill() + " " + st.getBoosted() + "/" + st.getReal())
				.collect(Collectors.joining(", ")));
		}
		return lines;
	}
}

package com.deathrecap;

import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.io.ByteArrayInputStream;
import java.io.DataInputStream;
import java.io.DataOutputStream;
import java.io.IOException;
import java.io.OutputStream;
import java.util.ArrayList;
import java.util.List;
import java.util.function.IntConsumer;
import javax.imageio.ImageIO;
import javax.imageio.ImageReader;
import javax.imageio.metadata.IIOMetadataNode;
import javax.imageio.stream.ImageInputStream;
import lombok.Value;

/**
 * Turns a saved replay GIF back into whole frames for the replay player. The GIF stores only the area
 * that changed, so each frame is drawn over the previous one; the results are kept as JPEGs so a long
 * full-size replay fits in a few tens of megabytes.
 */
final class ReplayFrames
{
	private static final String FORMAT = "javax_imageio_gif_image_1.0";
	/** Starts a replay's full-quality frames file: "DRF1". */
	private static final int MAGIC = 0x44524631;
	/** How long the last frame of a frames file is shown, matching the GIF's final delay. */
	static final int LAST_FRAME_MS = 1500;

	@Value
	static class Decoded
	{
		List<byte[]> frames;
		/** Display time of each frame, in milliseconds. */
		int[] durations;

		BufferedImage frame(int index) throws IOException
		{
			return FrameCodec.decode(frames.get(index));
		}
	}

	private ReplayFrames()
	{
	}

	/**
	 * Writes the frames as recorded, so videos made later don't suffer the GIF's 256 colours.
	 *
	 * @param times when each frame was captured, relative to the death in ms
	 */
	static void writeFrames(OutputStream out, List<byte[]> jpegs, int[] times) throws IOException
	{
		DataOutputStream data = new DataOutputStream(out);
		data.writeInt(MAGIC);
		data.writeInt(jpegs.size());
		for (int i = 0; i < jpegs.size(); i++)
		{
			data.writeInt(times[i]);
			data.writeInt(jpegs.get(i).length);
			data.write(jpegs.get(i));
		}
		data.flush();
	}

	/** Decodes either a frames file or a replay GIF. */
	static Decoded load(byte[] data, IntConsumer progress) throws IOException
	{
		if (data.length < 8 || data[0] != 'D' || data[1] != 'R' || data[2] != 'F' || data[3] != '1')
		{
			return decode(data, progress);
		}
		DataInputStream in = new DataInputStream(new ByteArrayInputStream(data));
		in.readInt();
		int count = in.readInt();
		if (count < 1 || count > 10_000)
		{
			throw new IOException("Bad frame count " + count);
		}
		List<byte[]> frames = new ArrayList<>(count);
		int[] times = new int[count];
		for (int i = 0; i < count; i++)
		{
			times[i] = in.readInt();
			int length = in.readInt();
			if (length < 0 || length > in.available())
			{
				throw new IOException("Truncated frames file");
			}
			byte[] jpeg = new byte[length];
			in.readFully(jpeg);
			frames.add(jpeg);
			progress.accept(i + 1);
		}
		int[] durations = new int[count];
		for (int i = 0; i < count - 1; i++)
		{
			durations[i] = Math.max(20, times[i + 1] - times[i]);
		}
		durations[count - 1] = LAST_FRAME_MS;
		return new Decoded(frames, durations);
	}

	/**
	 * @param progress told the number of frames done so far
	 */
	static Decoded decode(byte[] gif, IntConsumer progress) throws IOException
	{
		ImageReader reader = ImageIO.getImageReadersByFormatName("gif").next();
		try (ImageInputStream in = ImageIO.createImageInputStream(new ByteArrayInputStream(gif)))
		{
			reader.setInput(in, false, false);
			List<byte[]> frames = new ArrayList<>();
			List<Integer> durations = new ArrayList<>();
			BufferedImage canvas = null;
			for (int i = 0; ; i++)
			{
				BufferedImage part;
				try
				{
					part = reader.read(i);
				}
				catch (IndexOutOfBoundsException e)
				{
					break;
				}
				IIOMetadataNode root = (IIOMetadataNode) reader.getImageMetadata(i).getAsTree(FORMAT);
				IIOMetadataNode d = child(root, "ImageDescriptor");
				IIOMetadataNode gce = child(root, "GraphicControlExtension");
				int left = d != null ? Integer.parseInt(d.getAttribute("imageLeftPosition")) : 0;
				int top = d != null ? Integer.parseInt(d.getAttribute("imageTopPosition")) : 0;
				if (canvas == null)
				{
					canvas = new BufferedImage(left + part.getWidth(), top + part.getHeight(), BufferedImage.TYPE_INT_RGB);
				}
				Graphics2D g = canvas.createGraphics();
				g.drawImage(part, left, top, null);
				g.dispose();
				frames.add(FrameCodec.encode(canvas));
				int delay = gce != null ? Integer.parseInt(gce.getAttribute("delayTime")) : 10;
				durations.add(Math.max(20, delay * 10));
				progress.accept(frames.size());
			}
			if (frames.isEmpty())
			{
				throw new IOException("The replay has no frames");
			}
			return new Decoded(frames, durations.stream().mapToInt(Integer::intValue).toArray());
		}
		finally
		{
			reader.dispose();
		}
	}

	/**
	 * When each frame was captured, relative to the death in milliseconds. Uses the times saved with the
	 * recap when they match the replay; otherwise rebuilds them from the frame durations, assuming the
	 * recording ran {@link DeathCapture#AFTER_DEATH_MS} past the death.
	 */
	static int[] times(int[] saved, int[] durations)
	{
		if (saved != null && saved.length == durations.length)
		{
			return saved;
		}
		int[] times = new int[durations.length];
		int t = (int) DeathCapture.AFTER_DEATH_MS;
		for (int i = durations.length - 1; i >= 0; i--)
		{
			times[i] = t;
			if (i > 0)
			{
				t -= durations[i - 1];
			}
		}
		return times;
	}

	/** The last frame captured at or before {@code time}, or the first frame. */
	static int frameAt(int[] times, long time)
	{
		int found = 0;
		for (int i = 0; i < times.length; i++)
		{
			if (times[i] > time)
			{
				break;
			}
			found = i;
		}
		return found;
	}

	private static IIOMetadataNode child(IIOMetadataNode root, String name)
	{
		for (int i = 0; i < root.getLength(); i++)
		{
			if (root.item(i).getNodeName().equals(name))
			{
				return (IIOMetadataNode) root.item(i);
			}
		}
		return null;
	}
}

package com.deathrecap;

import java.awt.BorderLayout;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.GraphicsEnvironment;
import java.awt.Rectangle;
import java.awt.Window;
import java.awt.event.ActionEvent;
import java.awt.event.KeyEvent;
import java.awt.event.WindowAdapter;
import java.awt.event.WindowEvent;
import java.io.IOException;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.concurrent.Executor;
import java.util.function.Consumer;
import java.util.stream.Collectors;
import javax.swing.AbstractAction;
import javax.swing.DefaultListCellRenderer;
import javax.swing.ImageIcon;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.JComponent;
import javax.swing.JDialog;
import javax.swing.JLabel;
import javax.swing.JList;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JSlider;
import javax.swing.KeyStroke;
import javax.swing.ListSelectionModel;
import javax.swing.SwingUtilities;
import javax.swing.Timer;
import javax.swing.border.EmptyBorder;
import lombok.extern.slf4j.Slf4j;

/**
 * Plays a death replay at full size next to the recap's timeline. Clicking an event jumps to that
 * moment; while playing, the event list follows along. Space plays or pauses, the arrow keys step.
 */
@Slf4j
class ReplayPlayer extends JDialog
{
	private static final int MS_PER_TICK = 600;
	/** How long the player waits at the last frame before it counts as finished. */
	private static final int END_HOLD_MS = 1000;

	private final DeathRecord record;
	private final List<RecapEvent> events;
	private final List<ReplaySound> sounds;
	private final Consumer<ReplaySound> playSound;
	private final JLabel status = new JLabel("Loading replay...", JLabel.CENTER);
	private final Timer timer = new Timer(0, e -> advance());

	private ReplayFrames.Decoded decoded;
	private int[] times;
	private int current = -1;
	private boolean updating;
	private JLabel image;
	private JSlider slider;
	private JLabel clock;
	private JButton play;
	private JList<RecapEvent> list;

	/**
	 * @param startTick event tick to open at, paused; or null to play from the start
	 * @param extra shown next to "Copy folder path", or null
	 * @param playSound plays one of the record's sounds while the replay plays
	 */
	ReplayPlayer(Window owner, String title, DeathRecord record, byte[] replay, Integer startTick, Runnable copyFolderPath,
		JComponent extra, Executor executor, Consumer<ReplaySound> playSound)
	{
		super(owner, title);
		this.record = record;
		this.sounds = record.getReplaySounds() != null ? record.getReplaySounds() : Collections.emptyList();
		this.playSound = playSound;
		this.events = record.getEvents().stream()
			.sorted(Comparator.comparingInt(RecapEvent::getTick))
			.collect(Collectors.toList());
		setDefaultCloseOperation(DISPOSE_ON_CLOSE);
		setResizable(true);
		timer.setRepeats(false);
		status.setBorder(new EmptyBorder(40, 80, 40, 80));
		add(status, BorderLayout.CENTER);
		addWindowListener(new WindowAdapter()
		{
			@Override
			public void windowClosed(WindowEvent e)
			{
				timer.stop();
				decoded = null;
			}
		});
		pack();
		setLocationRelativeTo(owner);

		// Decoding takes a moment for long replays, so it runs off the Swing thread.
		executor.execute(() ->
		{
			try
			{
				ReplayFrames.Decoded d = ReplayFrames.load(replay, n -> SwingUtilities.invokeLater(() ->
					status.setText("Loading replay... " + n + " frames")));
				SwingUtilities.invokeLater(() -> ready(d, startTick, copyFolderPath, extra));
			}
			catch (IOException | RuntimeException e)
			{
				log.warn("Unable to load death replay", e);
				SwingUtilities.invokeLater(() -> status.setText("Unable to load this replay."));
			}
		});
	}

	private void ready(ReplayFrames.Decoded d, Integer startTick, Runnable copyFolderPath, JComponent extra)
	{
		if (!isDisplayable())
		{
			return;
		}
		decoded = d;
		times = ReplayFrames.times(record.getReplayTimes(), d.getDurations());
		getContentPane().removeAll();

		image = new JLabel();
		JScrollPane view = new JScrollPane(image);
		view.setBorder(null);
		view.getVerticalScrollBar().setUnitIncrement(24);
		view.getHorizontalScrollBar().setUnitIncrement(24);
		add(view, BorderLayout.CENTER);

		list = new JList<>(events.toArray(new RecapEvent[0]));
		list.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);
		list.setCellRenderer(new DefaultListCellRenderer()
		{
			@Override
			public Component getListCellRendererComponent(JList<?> l, Object value, int index, boolean selected, boolean focus)
			{
				RecapEvent e = (RecapEvent) value;
				super.getListCellRendererComponent(l, RecapText.offset(e.getTick(), record.getDeathTick()) + "  "
					+ RecapText.describe(e), index, selected, focus);
				if (!selected)
				{
					setForeground(DeathRecapPanel.colour(e));
				}
				return this;
			}
		});
		list.addListSelectionListener(e ->
		{
			if (!updating && !e.getValueIsAdjusting() && list.getSelectedValue() != null)
			{
				pause();
				seek(list.getSelectedValue().getTick());
			}
		});
		JScrollPane side = new JScrollPane(list);
		side.setPreferredSize(new Dimension(280, 0));
		JPanel right = new JPanel(new BorderLayout());
		JLabel hint = new JLabel("Click an event to jump to it");
		hint.setBorder(new EmptyBorder(4, 6, 4, 6));
		right.add(hint, BorderLayout.NORTH);
		right.add(side, BorderLayout.CENTER);
		add(right, BorderLayout.EAST);

		JPanel controls = new JPanel(new BorderLayout(8, 0));
		controls.setBorder(new EmptyBorder(4, 6, 4, 6));
		play = new JButton("Pause");
		play.addActionListener(e -> toggle());
		slider = new JSlider(0, times.length - 1, 0);
		slider.addChangeListener(e ->
		{
			if (!updating)
			{
				pause();
				show(slider.getValue());
			}
		});
		clock = new JLabel();
		JPanel west = new JPanel(new FlowLayout(FlowLayout.LEFT, 4, 0));
		west.add(play);
		west.add(clock);
		JButton folder = new JButton("Copy folder path");
		folder.addActionListener(e -> copyFolderPath.run());
		controls.add(west, BorderLayout.WEST);
		controls.add(slider, BorderLayout.CENTER);
		JPanel east = new JPanel(new FlowLayout(FlowLayout.RIGHT, 4, 0));
		if (extra != null)
		{
			east.add(extra);
		}
		east.add(folder);
		controls.add(east, BorderLayout.EAST);
		add(controls, BorderLayout.SOUTH);

		bind(KeyEvent.VK_SPACE, "toggle", this::toggle);
		bind(KeyEvent.VK_LEFT, "back", () -> step(-1));
		bind(KeyEvent.VK_RIGHT, "forward", () -> step(1));

		show(0);
		pack();
		// Full size where it fits; anything bigger scrolls instead of being shrunk.
		Rectangle usable = GraphicsEnvironment.getLocalGraphicsEnvironment().getMaximumWindowBounds();
		setSize(Math.min(getWidth(), usable.width), Math.min(getHeight(), usable.height));
		setLocationRelativeTo(getOwner());

		if (startTick != null)
		{
			pause();
			seek(startTick);
		}
		else
		{
			resume();
		}
	}

	private void bind(int key, String name, Runnable action)
	{
		JComponent root = getRootPane();
		root.getInputMap(JComponent.WHEN_IN_FOCUSED_WINDOW).put(KeyStroke.getKeyStroke(key, 0), name);
		root.getActionMap().put(name, new AbstractAction()
		{
			@Override
			public void actionPerformed(ActionEvent e)
			{
				action.run();
			}
		});
	}

	/** Shows the frame for an event's tick: ticks are 600 ms apart and the death is at time 0. */
	private void seek(int tick)
	{
		show(ReplayFrames.frameAt(times, (long) (tick - record.getDeathTick()) * MS_PER_TICK));
	}

	private void step(int by)
	{
		pause();
		show(Math.max(0, Math.min(times.length - 1, current + by)));
	}

	private void toggle()
	{
		if (timer.isRunning())
		{
			pause();
		}
		else
		{
			if (current >= times.length - 1)
			{
				show(0);
			}
			resume();
		}
	}

	private void pause()
	{
		timer.stop();
		if (play != null)
		{
			play.setText("Play");
		}
	}

	private void resume()
	{
		play.setText("Pause");
		schedule();
	}

	private void schedule()
	{
		int delay = current < times.length - 1 ? times[current + 1] - times[current] : END_HOLD_MS;
		timer.setInitialDelay(Math.max(20, Math.min(1000, delay)));
		timer.restart();
	}

	private void advance()
	{
		if (decoded == null)
		{
			return;
		}
		if (current >= times.length - 1)
		{
			pause();
			return;
		}
		long from = times[current];
		show(current + 1);
		// Only while playing: stepping and seeking stay quiet.
		for (ReplaySound s : sounds)
		{
			if (s.getTime() > from && s.getTime() <= times[current])
			{
				playSound.accept(s);
			}
		}
		schedule();
	}

	private void show(int index)
	{
		if (decoded == null)
		{
			return;
		}
		try
		{
			image.setIcon(new ImageIcon(decoded.frame(index)));
		}
		catch (IOException e)
		{
			log.debug("Unable to show replay frame {}", index, e);
		}
		current = index;
		updating = true;
		try
		{
			slider.setValue(index);
			long time = times[index];
			clock.setText(String.format("%s%.1fs", time > 0 ? "+" : time < 0 ? "-" : "", Math.abs(time) / 1000.0));
			int at = -1;
			for (int i = 0; i < events.size(); i++)
			{
				if ((long) (events.get(i).getTick() - record.getDeathTick()) * MS_PER_TICK <= time)
				{
					at = i;
				}
			}
			if (at >= 0)
			{
				list.setSelectedIndex(at);
				list.ensureIndexIsVisible(at);
			}
			else
			{
				list.clearSelection();
			}
		}
		finally
		{
			updating = false;
		}
	}
}

package com.deathrecap;

import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

/** A game sound effect heard during a replay, played again by the client when the replay is watched. */
@Data
@NoArgsConstructor
@AllArgsConstructor
public class ReplaySound
{
	/** When the sound played, in milliseconds relative to the record's timestamp, like the replay frames. */
	private int time;
	private int id;
	/** True for an area sound (hits, spells, monsters), false for one the player's own client plays. */
	private boolean area;
}

package com.deathrecap;

import com.deathrecap.video.H264Encoder;
import com.deathrecap.video.Mp4Writer;
import java.awt.Color;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InterruptedIOException;
import java.io.OutputStream;
import java.util.function.IntConsumer;

/**
 * Turns a saved replay into an MP4 with the pure-Java encoder in {@code com.deathrecap.video}, from its
 * full-quality frames when they're still kept or else its GIF. The uneven frame times are resampled to a
 * steady {@link #FPS}, and a clock, HP and the latest event are drawn along the bottom.
 */
final class ReplayVideo
{
	static final int FPS = 10;
	/** Lower is sharper and bigger; exports have no size limit, so this favours quality. */
	static final int QP = 20;
	private static final int MS_PER_TICK = 600;
	/** How long an event stays on screen. */
	private static final int CAPTION_MS = 1800;
	private static final Color SHADE = new Color(0, 0, 0, 0xB0);

	private ReplayVideo()
	{
	}

	/**
	 * @param maxWidth frames wider than this are scaled down; 0 keeps the recorded size
	 * @param progress told the percentage done
	 */
	static void write(byte[] replay, DeathRecord record, int maxWidth, Font font, OutputStream out, IntConsumer progress)
		throws IOException
	{
		ReplayFrames.Decoded decoded = ReplayFrames.load(replay, n -> { });
		int[] durations = decoded.getDurations();
		int[] times = ReplayFrames.times(record.getReplayTimes(), durations);
		int last = times.length - 1;
		long start = times[0];
		long end = times[last] + durations[last];
		int count = (int) Math.max(1, (end - start) * FPS / 1000);

		BufferedImage first = decoded.frame(0);
		double scale = maxWidth > 0 && first.getWidth() > maxWidth ? (double) maxWidth / first.getWidth() : 1;
		int width = Math.max(16, (int) Math.round(first.getWidth() * scale) & ~1);
		int height = Math.max(16, (int) Math.round(first.getHeight() * scale) & ~1);

		H264Encoder encoder = new H264Encoder(width, height, FPS);
		encoder.setKeyInterval(FPS * 2);
		encoder.setQp(QP);
		Mp4Writer mp4 = new Mp4Writer(width, height, FPS, encoder.sps(), encoder.pps());
		ByteArrayOutputStream media = new ByteArrayOutputStream();

		BufferedImage base = new BufferedImage(width, height, BufferedImage.TYPE_INT_RGB);
		BufferedImage canvas = new BufferedImage(width, height, BufferedImage.TYPE_INT_RGB);
		Font caption = font.deriveFont(Font.PLAIN, Math.max(12f, height / 24f));
		int[] pixels = new int[width * height];
		int shown = -1;
		for (int i = 0; i < count; i++)
		{
			if (Thread.currentThread().isInterrupted())
			{
				throw new InterruptedIOException("Export cancelled");
			}
			long time = start + (long) i * 1000 / FPS;
			int index = ReplayFrames.frameAt(times, time);
			if (index != shown)
			{
				BufferedImage frame = index == 0 ? first : decoded.frame(index);
				Graphics2D g = base.createGraphics();
				g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
				g.drawImage(frame, 0, 0, width, height, null);
				g.dispose();
				shown = index;
			}
			Graphics2D g = canvas.createGraphics();
			g.drawImage(base, 0, 0, null);
			caption(g, record, time, width, height, caption);
			g.dispose();
			canvas.getRGB(0, 0, width, height, pixels, 0, width);
			mp4.addFrame(encoder.encode(pixels, i == 0), media);
			progress.accept((i + 1) * 99 / count);
		}
		mp4.finish(out, new ByteArrayInputStream(media.toByteArray()));
		progress.accept(100);
	}

	/** The clock and HP on the left of the bottom bar, the latest event on the right. */
	private static void caption(Graphics2D g, DeathRecord record, long time, int width, int height, Font font)
	{
		g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
		g.setFont(font);
		FontMetrics fm = g.getFontMetrics();
		int pad = fm.getHeight() / 3;
		int bar = fm.getHeight() + pad * 2;
		g.setColor(SHADE);
		g.fillRect(0, height - bar, width, bar);
		int baseline = height - bar + pad + fm.getAscent();

		String clock = String.format("%s%.1fs", time < 0 ? "-" : "+", Math.abs(time) / 1000.0);
		TickSnapshot hp = null;
		for (TickSnapshot t : record.getTicks())
		{
			long at = (long) (t.getTick() - record.getDeathTick()) * MS_PER_TICK;
			if (at <= time && (hp == null || t.getTick() > hp.getTick()))
			{
				hp = t;
			}
		}
		g.setColor(Color.WHITE);
		g.drawString(clock, pad, baseline);
		int x = pad + fm.stringWidth("-00.0s") + pad * 2;
		if (hp != null)
		{
			g.setColor(HpGraph.HP);
			g.drawString("HP " + hp.getHp() + "/" + hp.getMaxHp(), x, baseline);
		}

		RecapEvent latest = null;
		for (RecapEvent e : record.getEvents())
		{
			long at = (long) (e.getTick() - record.getDeathTick()) * MS_PER_TICK;
			if (at <= time && time - at < CAPTION_MS && shown(e) && (latest == null || e.getTick() >= latest.getTick()))
			{
				latest = e;
			}
		}
		String text = latest != null ? RecapText.describe(latest)
			: record.isDeath() && time >= 0 && time < CAPTION_MS ? "Died" : null;
		if (text != null)
		{
			g.setColor(latest == null || latest.isDamage() ? HpGraph.HIT
				: latest.getType() == RecapEvent.Type.EAT || latest.getType() == RecapEvent.Type.DRINK ? HpGraph.FOOD
				: Color.WHITE);
			g.drawString(text, Math.max(x, width - pad - fm.stringWidth(text)), baseline);
		}
	}

	private static boolean shown(RecapEvent e)
	{
		switch (e.getType())
		{
			case ATTACK:
			case PROJECTILE:
				return false;
			default:
				return true;
		}
	}
}

package com.deathrecap;

import java.awt.Color;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;

/**
 * One image to share a death, in one of several {@link ShareCardLayout layouts}: the screenshot at full
 * size with the killer, the killing blow, what was lost, damage by source, the main findings, the items
 * lost and the HP graph. Every layout is laid out twice: once to measure, once to draw.
 */
final class ShareCard
{
	private static final Color BACKGROUND = new Color(0x24, 0x24, 0x24);
	private static final Color PANEL = new Color(0x1E, 0x1E, 0x1E);
	private static final Color TEXT = new Color(0xE6, 0xE6, 0xE6);
	private static final Color MUTED = new Color(0x9A, 0x9A, 0x9A);
	private static final Color BAR = new Color(0x48, 0x48, 0x48);
	private static final int MIN_WIDTH = 900;
	private static final int COMPACT_WIDTH = 1100;
	private static final int SOURCES = 5;
	private static final int FINDINGS = 5;
	private static final int ITEMS = 6;
	private static final String CREDIT = "Death Recap for RuneLite";

	private ShareCard()
	{
	}

	/** One part of the card, drawn at (x, y) within width w; returns its height, 0 if it has nothing to show. */
	private interface Block
	{
		int paint(int x, int y, int w);
	}

	/**
	 * @param screenshot the death screenshot, or null to draw the recap alone
	 * @param font text font, scaled to the card's size
	 * @param bold title font, scaled to the card's size
	 */
	static BufferedImage render(BufferedImage screenshot, DeathRecord record, RecapAnalyzer.Summary summary, Font font, Font bold, ShareCardLayout layout)
	{
		if (screenshot == null || layout == ShareCardLayout.COMPACT)
		{
			return layout == ShareCardLayout.TALL ? tall(null, record, summary, font, bold) : wide(null, record, summary, font, bold);
		}
		switch (layout)
		{
			case SIDE:
				return side(screenshot, record, summary, font, bold);
			case TALL:
				return tall(screenshot, record, summary, font, bold);
			default:
				return wide(screenshot, record, summary, font, bold);
		}
	}

	static BufferedImage render(BufferedImage screenshot, DeathRecord record, RecapAnalyzer.Summary summary, Font font, Font bold)
	{
		return render(screenshot, record, summary, font, bold, ShareCardLayout.WIDE);
	}

	/** The screenshot with three columns underneath: who and how much, what happened, the graph. */
	private static BufferedImage wide(BufferedImage shot, DeathRecord record, RecapAnalyzer.Summary summary, Font font, Font bold)
	{
		int width = shot != null ? Math.max(MIN_WIDTH, shot.getWidth()) : COMPACT_WIDTH;
		float k = clamp(width / 1000f, 1f, 2f);
		Painter m = Painter.measure(record, summary, font, bold, k);
		int pad = m.pad;
		int colGap = pad * 2;
		int inner = width - pad * 2 - colGap * 2;
		int w1 = (int) (inner * 0.30);
		int w2 = (int) (inner * 0.33);
		int w3 = inner - w1 - w2;
		int content = Math.max(Math.round(240 * k), Math.max(
			m.column(0, 0, w1, m::header, m::loss, m::sources),
			m.column(0, 0, w2, m::tiles, m::findings, m::items)));
		int shotHeight = shot != null ? shot.getHeight() : 0;
		int stripHeight = pad + content + m.creditHeight();

		BufferedImage out = new BufferedImage(width, shotHeight + stripHeight, BufferedImage.TYPE_INT_RGB);
		Painter p = Painter.draw(out, record, summary, font, bold, k);
		try
		{
			p.fill(BACKGROUND, 0, 0, width, out.getHeight());
			if (shot != null)
			{
				p.g.drawImage(shot, (width - shot.getWidth()) / 2, 0, null);
			}
			int top = shotHeight + pad;
			p.column(pad, top, w1, p::header, p::loss, p::sources);
			p.column(pad + w1 + colGap, top, w2, p::tiles, p::findings, p::items);
			p.graph(width - pad - w3, top, w3, content);
			p.credit(width, out.getHeight());
		}
		finally
		{
			p.g.dispose();
		}
		return out;
	}

	/** The screenshot with everything in one column to its right. */
	private static BufferedImage side(BufferedImage shot, DeathRecord record, RecapAnalyzer.Summary summary, Font font, Font bold)
	{
		float k = clamp(shot.getHeight() / 720f, 1f, 2f);
		Painter m = Painter.measure(record, summary, font, bold, k);
		int pad = m.pad;
		int panelWidth = Math.round(470 * k);
		int inner = panelWidth - pad * 2;
		int graphHeight = Math.round(190 * k);
		Block graph = (x, y, w) -> m.graph(x, y, w, graphHeight);
		int content = m.column(0, 0, inner, m::header, m::loss, m::tiles, graph, m::sources, m::findings, m::items);
		int width = shot.getWidth() + panelWidth;
		int height = Math.max(shot.getHeight(), pad + content + m.creditHeight());

		BufferedImage out = new BufferedImage(width, height, BufferedImage.TYPE_INT_RGB);
		Painter p = Painter.draw(out, record, summary, font, bold, k);
		try
		{
			p.fill(BACKGROUND, 0, 0, width, height);
			p.fill(PANEL, shot.getWidth(), 0, panelWidth, height);
			p.g.drawImage(shot, 0, (height - shot.getHeight()) / 2, null);
			p.column(shot.getWidth() + pad, pad, inner, p::header, p::loss, p::tiles, (x, y, w) -> p.graph(x, y, w, graphHeight),
				p::sources, p::findings, p::items);
			p.credit(width, height);
		}
		finally
		{
			p.g.dispose();
		}
		return out;
	}

	/** The screenshot on top, then the headline, a full-width graph and two columns, in larger text. */
	private static BufferedImage tall(BufferedImage shot, DeathRecord record, RecapAnalyzer.Summary summary, Font font, Font bold)
	{
		int width = shot != null ? Math.max(1080, shot.getWidth()) : 1080;
		float k = clamp(width / 850f, 1.2f, 2.4f);
		Painter m = Painter.measure(record, summary, font, bold, k);
		int pad = m.pad;
		int inner = width - pad * 2;
		int colWidth = (inner - pad * 2) / 2;
		int graphHeight = Math.round(230 * k);
		int header = m.column(0, 0, inner, m::header, m::loss, m::tiles);
		int columns = Math.max(m.column(0, 0, colWidth, m::sources, m::items), m.column(0, 0, colWidth, m::findings));
		int shotHeight = shot != null ? shot.getHeight() : 0;
		int height = shotHeight + pad + header + m.gap + graphHeight + (columns > 0 ? m.gap + columns : 0) + m.creditHeight();

		BufferedImage out = new BufferedImage(width, height, BufferedImage.TYPE_INT_RGB);
		Painter p = Painter.draw(out, record, summary, font, bold, k);
		try
		{
			p.fill(BACKGROUND, 0, 0, width, height);
			if (shot != null)
			{
				p.g.drawImage(shot, (width - shot.getWidth()) / 2, 0, null);
			}
			int y = shotHeight + pad;
			p.column(pad, y, inner, p::header, p::loss, p::tiles);
			y += header + p.gap;
			p.graph(pad, y, inner, graphHeight);
			y += graphHeight + p.gap;
			p.column(pad, y, colWidth, p::sources, p::items);
			p.column(width - pad - colWidth, y, colWidth, p::findings);
			p.credit(width, height);
		}
		finally
		{
			p.g.dispose();
		}
		return out;
	}

	/** Lays out and, unless measuring, draws the card's blocks. */
	private static final class Painter
	{
		final Graphics2D g;
		final boolean draw;
		final DeathRecord record;
		final RecapAnalyzer.Summary summary;
		final ItemsOnDeath.Result items;
		final Font body;
		final Font small;
		final Font title;
		final Font heading;
		final float k;
		final int pad;
		final int gap;

		private Painter(Graphics2D g, boolean draw, DeathRecord record, RecapAnalyzer.Summary summary, Font font, Font bold, float k)
		{
			this.g = g;
			this.draw = draw;
			this.record = record;
			this.summary = summary;
			this.items = !record.isDeath() || record.getState() == null ? null : ItemsOnDeath.compute(record.getState());
			this.k = k;
			body = font.deriveFont(16 * k);
			small = font.deriveFont(14 * k);
			title = bold.deriveFont(26 * k);
			heading = bold.deriveFont(17 * k);
			pad = Math.round(18 * k);
			gap = Math.round(14 * k);
			g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		}

		static Painter measure(DeathRecord record, RecapAnalyzer.Summary summary, Font font, Font bold, float k)
		{
			return new Painter(new BufferedImage(1, 1, BufferedImage.TYPE_INT_RGB).createGraphics(), false, record, summary, font, bold, k);
		}

		static Painter draw(BufferedImage out, DeathRecord record, RecapAnalyzer.Summary summary, Font font, Font bold, float k)
		{
			return new Painter(out.createGraphics(), true, record, summary, font, bold, k);
		}

		/** Blocks stacked top to bottom with a gap between those that show something. */
		int column(int x, int y, int w, Block... blocks)
		{
			int h = 0;
			for (Block b : blocks)
			{
				int space = h > 0 ? gap : 0;
				int bh = b.paint(x, y + h + space, w);
				if (bh > 0)
				{
					h += space + bh;
				}
			}
			return h;
		}

		/** Who did it in large type, then their level and weapon, the killing blow, and when and where. */
		int header(int x, int y, int w)
		{
			Color colour = record.isCloseCall() ? HpGraph.FOOD : record.isClip() ? HpGraph.PRAYER : HpGraph.HIT;
			String name = summary.getKiller();
			boolean fought = summary.getTotalDamage() > 0 && name != null;
			String head = record.isClip() ? (fought ? "Clip, fighting " + name : "Clip")
				: (record.isCloseCall() ? "Close call against " : "Killed by ") + name;
			int h = lines(head, title, colour, x, y, w);
			String who = fought ? who(name) : "";
			if (!who.isEmpty())
			{
				h += lines(who, heading, TEXT, x, y + h, w);
			}
			String line = headline(record, summary);
			if (!line.isEmpty())
			{
				h += lines(line, body, Color.LIGHT_GRAY, x, y + h, w);
			}
			h += put(RecapText.date(record.getTimestamp()) + " · " + RecapText.place(record), body, MUTED, x, y + h, w);
			return h;
		}

		/** "Level 126 player · Armadyl godsword", or just the level for NPCs; empty when nothing is known. */
		private String who(String name)
		{
			Attacker a = record.attacker(name);
			List<String> parts = new ArrayList<>();
			if (a != null && a.getCombatLevel() > 0)
			{
				parts.add("Level " + a.getCombatLevel() + (a.isPlayer() ? " player" : ""));
			}
			else if (a != null && a.isPlayer())
			{
				parts.add("Player");
			}
			String weapon = RecapText.killerWeapon(record, summary);
			if (weapon != null)
			{
				parts.add(weapon);
			}
			return String.join(" · ", parts);
		}

		/** A row of key numbers: damage taken, damage per second, biggest hit and food eaten. */
		int tiles(int x, int y, int w)
		{
			if (summary.getTotalDamage() == 0)
			{
				return 0;
			}
			List<String[]> list = new ArrayList<>();
			int deathTick = record.getDeathTick();
			int first = Integer.MAX_VALUE;
			int biggest = 0;
			int eaten = 0;
			for (RecapEvent e : record.getEvents())
			{
				if (e.getTick() > deathTick)
				{
					continue;
				}
				if (e.isDamage())
				{
					first = Math.min(first, e.getTick());
					biggest = Math.max(biggest, e.getAmount());
				}
				else if (e.getType() == RecapEvent.Type.EAT || e.getType() == RecapEvent.Type.DRINK)
				{
					eaten++;
				}
			}
			list.add(new String[]{String.valueOf(summary.getTotalDamage()), "damage"});
			// Counted the same way as the damage finding: every tick from the first hit to the death.
			int span = deathTick - first + 1;
			if (first != Integer.MAX_VALUE && span >= 3)
			{
				list.add(new String[]{String.format(Locale.ROOT, "%.1f", summary.getTotalDamage() / (span * 0.6)), "dmg / sec"});
			}
			list.add(new String[]{String.valueOf(biggest), "max hit"});
			if (record.isCloseCall())
			{
				int lowest = record.getTicks().stream().mapToInt(TickSnapshot::getHp).filter(v -> v > 0).min().orElse(0);
				list.add(new String[]{String.valueOf(lowest), "lowest HP"});
			}
			else
			{
				list.add(new String[]{String.valueOf(eaten), "eaten"});
			}

			FontMetrics fm = g.getFontMetrics(small);
			int tileGap = Math.round(6 * k);
			int tw = (w - tileGap * (list.size() - 1)) / list.size();
			int inner = Math.round(6 * k);
			int th = inner * 2 + g.getFontMetrics(title).getHeight() + fm.getHeight();
			for (int i = 0; i < list.size(); i++)
			{
				int tx = x + i * (tw + tileGap);
				if (draw)
				{
					g.setColor(PANEL);
					g.fillRoundRect(tx, y, tw, th, inner, inner);
				}
				Color c = i == 0 ? HpGraph.HIT : TEXT;
				int vh = put(list.get(i)[0], title, c, tx + inner, y + inner, tw - inner * 2);
				put(list.get(i)[1], small, MUTED, tx + inner, y + inner + vh, tw - inner * 2);
			}
			return th;
		}

		/** The value lost, in large type. */
		int loss(int x, int y, int w)
		{
			if (items == null)
			{
				return 0;
			}
			String lost = items.getAtRisk().isEmpty() ? "Nothing lost" : "Lost " + ItemsOnDeath.gp(items.getRiskValue()) + " gp";
			int h = lines(lost, title, HpGraph.FOOD, x, y, w);
			String note = items.getAtRisk().isEmpty() ? "" : "Estimate at Grand Exchange prices";
			if (items.getKeptValue() > 0)
			{
				note = "Kept " + ItemsOnDeath.gp(items.getKeptValue()) + " gp" + (note.isEmpty() ? "" : " · " + note);
			}
			if (!note.isEmpty())
			{
				h += lines(note, small, MUTED, x, y + h, w);
			}
			return h;
		}

		int sources(int x, int y, int w)
		{
			List<RecapAnalyzer.SourceDamage> list = summary.getBySource();
			if (list.isEmpty())
			{
				return 0;
			}
			int h = put("Damage by source", heading, TEXT, x, y, w);
			FontMetrics fm = g.getFontMetrics(body);
			int max = Math.max(1, list.get(0).getDamage());
			for (int i = 0; i < Math.min(SOURCES, list.size()); i++)
			{
				RecapAnalyzer.SourceDamage s = list.get(i);
				String amount = s.getDamage() + " (" + s.getHits() + (s.getHits() == 1 ? " hit)" : " hits)");
				int amountWidth = fm.stringWidth(amount);
				put(s.getSource(), body, TEXT, x, y + h, w - amountWidth - pad);
				put(amount, body, TEXT, x + w - amountWidth, y + h, amountWidth);
				h += fm.getHeight();
				int barHeight = Math.round(4 * k);
				fill(BAR, x, y + h, w, barHeight);
				fill(HpGraph.HIT, x, y + h, Math.max(1, w * s.getDamage() / max), barHeight);
				h += barHeight + Math.round(5 * k);
			}
			return h;
		}

		int findings(int x, int y, int w)
		{
			List<String> list = ShareCard.findings(summary);
			if (list.isEmpty())
			{
				return 0;
			}
			int h = put(record.isDeath() ? "What happened" : "How it went", heading, TEXT, x, y, w);
			for (String f : list)
			{
				for (String line : wrap("• " + f, g.getFontMetrics(body), w))
				{
					h += put(line, body, Color.LIGHT_GRAY, x, y + h, w);
				}
			}
			return h;
		}

		/** The most valuable items lost, with their value. */
		int items(int x, int y, int w)
		{
			if (items == null || items.getAtRisk().isEmpty())
			{
				return 0;
			}
			List<DeathState.ItemStack> lost = items.getAtRisk();
			int h = put("Items lost", heading, TEXT, x, y, w);
			FontMetrics fm = g.getFontMetrics(body);
			int shown = lost.size() > ITEMS ? ITEMS - 1 : lost.size();
			for (int i = 0; i < shown; i++)
			{
				DeathState.ItemStack s = lost.get(i);
				long value = s.getPrice() * s.getQuantity();
				String gp = value > 0 ? ItemsOnDeath.gp(value) : "-";
				int gpWidth = fm.stringWidth(gp);
				put(RecapText.stack(s), body, TEXT, x, y + h, w - gpWidth - pad);
				h += put(gp, body, HpGraph.FOOD, x + w - gpWidth, y + h, gpWidth);
			}
			if (shown < lost.size())
			{
				long rest = 0;
				for (int i = shown; i < lost.size(); i++)
				{
					rest += lost.get(i).getPrice() * lost.get(i).getQuantity();
				}
				h += put("+ " + (lost.size() - shown) + " more · " + ItemsOnDeath.gp(rest) + " gp", body, MUTED, x, y + h, w);
			}
			return h;
		}

		int graph(int x, int y, int w, int h)
		{
			if (draw)
			{
				g.setFont(small);
				HpGraph.paint(g, new Rectangle(x, y, w, h), record);
			}
			return h;
		}

		int creditHeight()
		{
			return g.getFontMetrics(small).getHeight() + pad / 2;
		}

		void credit(int width, int height)
		{
			FontMetrics fm = g.getFontMetrics(small);
			g.setFont(small);
			g.setColor(MUTED);
			g.drawString(CREDIT, width - pad - fm.stringWidth(CREDIT), height - pad / 2 - fm.getDescent());
		}

		void fill(Color colour, int x, int y, int w, int h)
		{
			if (draw)
			{
				g.setColor(colour);
				g.fillRect(x, y, w, h);
			}
		}

		/** Text wrapped to the width; returns the height of its lines. */
		private int lines(String text, Font font, Color colour, int x, int y, int w)
		{
			int h = 0;
			for (String line : wrap(text, g.getFontMetrics(font), w, ""))
			{
				h += put(line, font, colour, x, y + h, w);
			}
			return h;
		}

		/** One line of text, shortened to fit; returns the line's height. */
		private int put(String text, Font font, Color colour, int x, int y, int w)
		{
			FontMetrics fm = g.getFontMetrics(font);
			if (draw)
			{
				g.setFont(font);
				g.setColor(colour);
				g.drawString(fit(text, fm, w), x, y + fm.getAscent());
			}
			return fm.getHeight();
		}
	}

	private static float clamp(float v, float min, float max)
	{
		return Math.max(min, Math.min(max, v));
	}

	private static String headline(DeathRecord record, RecapAnalyzer.Summary summary)
	{
		if (record.isCloseCall())
		{
			int lowest = record.getTicks().stream().mapToInt(TickSnapshot::getHp).filter(h -> h > 0).min().orElse(0);
			return "Survived on " + lowest + " HP";
		}
		RecapEvent blow = summary.getKillingBlow();
		if (record.isClip() || blow == null)
		{
			return "";
		}
		// HP just before the killing blow shows whether it was one big hit or the last of many.
		int before = 0;
		for (TickSnapshot t : record.getTicks())
		{
			if (t.getTick() < blow.getTick())
			{
				before = t.getHp();
			}
		}
		return "Killing blow: " + blow.getAmount() + " damage" + (before > 0 ? ", you had " + before + " HP" : "");
	}

	/** The findings worth a place on the card; the killing blow is already in the headline. */
	private static List<String> findings(RecapAnalyzer.Summary summary)
	{
		List<String> out = new ArrayList<>();
		for (String f : summary.getFindings())
		{
			if (!f.startsWith("Killing blow") && out.size() < FINDINGS)
			{
				out.add(f);
			}
		}
		return out;
	}

	static List<String> wrap(String text, FontMetrics fm, int width)
	{
		return wrap(text, fm, width, "  ");
	}

	/** Words wrapped to the width, with {@code indent} before each line after the first. */
	static List<String> wrap(String text, FontMetrics fm, int width, String indent)
	{
		List<String> lines = new ArrayList<>();
		StringBuilder current = new StringBuilder();
		for (String word : text.split(" "))
		{
			String next = current.length() == 0 ? word : current + " " + word;
			if (fm.stringWidth(next) > width && current.length() > 0)
			{
				lines.add(current.toString());
				current = new StringBuilder(indent + word);
			}
			else
			{
				current = new StringBuilder(next);
			}
		}
		if (current.length() > 0)
		{
			lines.add(current.toString());
		}
		return lines;
	}

	private static String fit(String text, FontMetrics fm, int width)
	{
		if (fm.stringWidth(text) <= width)
		{
			return text;
		}
		String s = text;
		while (s.length() > 1 && fm.stringWidth(s + "...") > width)
		{
			s = s.substring(0, s.length() - 1);
		}
		return s + "...";
	}
}

